(window.TNQ=window.TNQ||[]).push({"terms":{"소상인":{"d":"자본금 규모가 작은 상인으로 지배인·상호·상업장부·상업등기 규정이 적용되지 않는다.","r":[]},"지배인":{"d":"영업주를 대신해 영업에 관한 재판상·재판외의 모든 행위를 할 수 있는 상업사용인이다.","r":[]},"개입권":{"d":"경업금지를 어긴 거래를 영업주의 계산으로 한 것으로 보는 영업주의 권리이다.","r":[]},"주식매수청구":{"d":"영업양도 등에 반대하는 주주가 회사에 자기 주식을 공정한 가격에 사 달라고 요구하는 권리이다.","r":[]},"사후설립":{"d":"회사 성립 후 일정 기간 안에 성립 전부터 있던 영업용 재산을 일정 비율 이상의 대가로 취득하는 계약이다.","r":[]},"기본적 상행위":{"d":"영업으로 하는 매매·임대차·제조·운송 등 상법이 열거한 상행위이다.","r":[]},"익명조합":{"d":"익명조합원이 영업자에게 출자하고 영업자는 이익을 분배하는 계약으로 출자 재산은 영업자의 것이 된다.","r":[]},"대리상":{"d":"상업사용인이 아니면서 일정한 상인을 위해 상시 영업부류의 거래를 대리하거나 중개하는 사람이다.","r":["위탁매매인"]},"중개인":{"d":"타인 간의 상행위를 중개하는 것을 영업으로 하는 사람이다.","r":[]},"위탁매매인":{"d":"자기 이름으로 타인의 계산으로 물건이나 유가증권의 매매를 영업으로 하는 사람이다.","r":["대리상"]},"금융리스":{"d":"리스업자가 이용자가 선정한 물건을 취득해 이용하게 하고 리스료를 받는 계약이다.","r":[]},"발기인":{"d":"주식회사의 설립을 기획하고 정관에 기명날인하거나 서명하는 사람이다.","r":[]},"변태설립사항":{"d":"발기인의 특별이익, 현물출자, 재산인수, 설립비용처럼 정관에 적어야 효력이 있는 설립 관련 사항이다.","r":[]},"검사인":{"d":"법원이 선임해 변태설립사항 등을 조사하고 보고하는 사람이다.","r":[]},"창립총회":{"d":"모집설립에서 인수인이 모여 임원 선임과 설립 사항을 결정하는 총회이다.","r":[]},"무액면주식":{"d":"액면금액이 없고 주식 수 비율로만 권리를 나타내는 주식이다.","r":[]},"종류주식":{"d":"이익배당, 잔여재산분배, 의결권 등에서 내용이 다르게 정해진 주식이다.","r":[]},"불소지":{"d":"주주가 주권을 소지하지 않겠다고 회사에 신고해 주권을 발행하지 않게 하는 제도이다.","r":[]},"선의취득":{"d":"권리 없는 자로부터 증권을 악의·중과실 없이 취득하면 권리를 얻는 제도이다.","r":[]},"명의개서":{"d":"주식 양수인의 성명과 주소를 주주명부에 적어 회사에 대항할 수 있게 하는 절차이다.","r":[]},"자기주식":{"d":"회사가 자기 회사의 주식을 취득해 가지는 것으로 배당가능이익 한도 등 규제를 받는다.","r":[]},"주식매수선택권":{"d":"회사가 임직원에게 정해진 가격에 신주를 인수하거나 자기주식을 매수할 수 있도록 주는 권리이다.","r":[]},"지배주주":{"d":"발행주식총수의 상당 비율을 가진 주주로 소수주주에게 주식 매도를 청구할 수 있다.","r":[]},"주주제안":{"d":"일정 지분을 가진 주주가 총회 목적사항을 이사에게 제안하는 권리이다.","r":[]},"집중투표":{"d":"이사 여러 명을 뽑을 때 주주가 가진 의결권을 한 사람에게 몰아줄 수 있는 선임 방식이다.","r":[]},"표현대표이사":{"d":"사장·전무 같은 명칭을 써서 대표권이 있는 것처럼 행동하는 이사로 선의 제3자에게 회사가 책임진다.","r":[]},"집행임원":{"d":"이사회가 선임해 업무집행을 맡고 대표이사를 대신하는 임원이다.","r":[]},"독립이사":{"d":"상장회사에서 회사와 중요한 이해관계가 없어 독립적으로 감독하는 사외이사이다.","r":[]},"감사위원회":{"d":"정관에 따라 감사에 갈음해 설치하는 이사회 내 위원회로 사외이사가 일정 비율 이상이어야 한다.","r":[]},"대표소송":{"d":"소수주주가 회사를 위해 이사의 책임을 묻는 소를 대신 제기하는 제도이다.","r":[]},"신주인수권":{"d":"주주가 가진 주식 수에 비례해 신주를 배정받을 수 있는 권리이다.","r":[]},"사채관리회사":{"d":"사채권자를 위해 변제 수령 등 사채 관리를 맡는 회사이다.","r":[]},"전환사채":{"d":"사채권자가 주식으로 전환할 수 있는 권리가 붙은 사채이다.","r":[]},"이익준비금":{"d":"배당액의 일정 비율을 자본금의 절반이 될 때까지 의무적으로 적립해 두는 법정준비금이다.","r":[]},"주식배당":{"d":"이익배당을 금전이 아니라 새로 발행하는 주식으로 지급하는 것이다.","r":[]},"중간배당":{"d":"영업연도 중에 이사회 결의로 일정한 날의 주주에게 배당하는 것이다.","r":[]},"조직변경":{"d":"회사가 법인격을 유지한 채 다른 종류의 회사로 바꾸는 것이다.","r":[]},"휴면회사":{"d":"최후 등기 후 오랫동안 등기하지 않은 회사로 해산한 것으로 간주될 수 있다.","r":[]},"임의청산":{"d":"합명·합자회사가 정관이나 사원의 동의로 정한 방법으로 재산을 처분하는 청산이다.","r":[]},"유한책임회사":{"d":"사원 모두가 출자금액을 한도로 책임지고 업무집행자가 경영을 맡는 회사이다.","r":[]},"어음":{"d":"일정한 금액의 지급을 약속하거나 위탁하는 유가증권으로 설권증권이며 요식증권이다.","r":[]},"백지어음":{"d":"어음요건 일부를 비워 두고 나중에 보충하기로 하고 발행한 어음이다.","r":[]},"배서":{"d":"어음을 양도하려고 뒷면에 기명날인하는 행위이다.","r":[]},"입질배서":{"d":"어음에 질권을 설정할 목적으로 하는 배서이다.","r":[]},"기한후배서":{"d":"지급거절증서 작성 후나 작성기간 경과 후에 한 배서로 지명채권 양도의 효력만 있다.","r":[]},"인적 항변":{"d":"어음채무자가 특정 소지인이나 종전 소지인과의 관계에서 갖는 항변으로 선의 취득자에게는 절단된다.","r":["물적 항변"]},"물적 항변":{"d":"어음 자체에서 비롯된 항변으로 소지인의 선의·악의와 상관없이 누구에게나 주장할 수 있다.","r":["인적 항변"]},"융통어음":{"d":"타인이 제3자에게서 금융을 얻게 할 목적으로 수수하는 어음이다.","r":[]},"상환청구":{"d":"만기에 지급이 거절되었을 때 소지인이 배서인·발행인 등에게 어음금액의 지급을 청구하는 것이다.","r":[]},"거절증서":{"d":"인수나 지급이 거절되었음을 공적으로 증명하는 증서이다.","r":[]},"이득상환청구권":{"d":"어음상 권리가 소멸한 뒤 채무자가 얻은 이익의 한도에서 소지인이 상환을 청구하는 권리이다.","r":[]},"자기앞수표":{"d":"은행이 발행인이자 지급인이 되어 발행하는 수표이다.","r":[]},"선일자수표":{"d":"발행일을 실제 발행일보다 뒤의 날짜로 적은 수표이다.","r":[]},"지급보증":{"d":"수표 지급인이 지급을 보증한다는 뜻을 적어 책임을 지는 행위이다.","r":[]}},"notes":{"1% 이상 주주가 이유를 적은 서면으로 회사에 소 제기를 청구 → 회사가 30일 내에 제기하지 않으면(회복할 수 없는 손해 염려가 있으면 즉시) 본점소재지 지방법원에 대표소송 제기 → 제소 후 1% 미만이 되어도 효력이 유지되나 주식을 전혀 갖지 않게 되면 원고적격을 잃는다 → 취하·포기·인락·화해는 법원 허가가 필요하고 회사는 허가 없이 참가할 수 있다 → 승소 주주는 소송비용 외 상당한 비용을 회사에 청구하고 패소 주주는 악의가 있을 때만 배상한다 → 다중대표소송은 모회사 1% 주주가 자회사 이사에 대하여 같은 방식으로 제기하고 자회사도 참가할 수 있다":"대표소송은 소수주주가 회사에 먼저 소 제기를 요구한 뒤 회사가 30일 안에 안 하면 지방법원에 제기하며 취하·화해에는 법원 허가가 필요합니다.","1월 이상의 주권제출기간을 공고·통지하고 그 기간이 끝난 때 효력이 생기며 채권자보호절차가 끝나지 않았으면 끝난 때 생긴다":"주식병합은 1월 이상의 주권제출기간을 공고·통지해 그 기간이 끝난 때 효력이 생기고, 채권자보호절차가 늦게 끝났으면 그때 효력이 생깁니다.","2025.7.22 개정 제382조의3은 이사가 회사 및 주주를 위하여 직무를 충실히 수행하고 총주주의 이익을 보호하며 전체 주주의 이익을 공평하게 대우하도록 정한다":"2025.7.22 개정 제382조의3은 이사가 회사와 주주를 위해 충실히 일하고 전체 주주를 공평하게 대우하도록 정했습니다.","2025.9.9 개정으로 위원 중 2명(정관으로 3명 이상 가능)은 다른 이사와 분리하여 선임한다":"위원 중 일부는 다른 이사와 분리해 뽑으며, 2025.9.9 개정으로 그 수가 2명, 정관으로 3명 이상으로 정해집니다.","2인 이상의 사원이 정관을 작성하고 총사원이 기명날인·서명하며, 정관에는 모든 사원의 성명·주민등록번호·주소와 출자의 목적·가격을 적는다":"합명회사는 사원 2인 이상이 정관을 만들어 총사원이 서명하며, 정관에는 사원 인적사항과 출자의 목적·가격을 적습니다.","2인 이상의 이사(감사위원회는 3명 이상)로 구성하고, 총회 승인사항의 제안, 대표이사 선임·해임, 위원회 설치·위원 선임은 위임하지 못하며 이사회는 감사위원회 외 위원회의 결의를 다시 결의할 수 있다":"위원회는 이사 2인 이상이 구성하고, 대표이사 선임은 위임할 수 없으며 이사회는 감사위원회 외 위원회 결의를 다시 결의할 수 있습니다.","2인 이상의 이사를 선임하는 총회에서 의결권 없는 주식을 뺀 3% 이상 주주는 정관으로 배제하지 않았으면 총회일 7일 전까지 서면·전자문서로 집중투표를 청구할 수 있다":"3% 이상 주주는 정관이 배제하지 않았다면 총회일 7일 전까지 이사 2인 이상 선임에 집중투표를 청구할 수 있습니다.","2주간 전에 공고하고, 신주인수권자에게 청약하지 않으면 권리를 잃는다는 뜻을 통지한다":"배정기준일은 2주 전에 공고하고 청약하지 않으면 권리를 잃는다는 뜻을 통지해야 합니다.","3% 이상 주주는 이유를 붙인 서면으로 회계장부 열람·등사를 청구하고, 회사는 청구가 부당함을 증명하지 못하면 거부하지 못한다":"3% 이상 주주는 이유를 적은 서면으로 회계장부 열람을 청구하고, 회사는 부당함을 증명하지 못하면 거부할 수 없습니다.","3명 이상의 이사로 구성하되 사외이사가 3분의 2 이상이어야 한다":"감사위원회는 이사 3명 이상으로 구성하고 사외이사가 3분의 2 이상이어야 합니다.","6월 내에 발견해 통지해야 해제·감액·손해배상을 청구할 수 있다":"바로 발견하지 못하는 하자는 6월 안에 발견해 통지해야 해제·감액·손해배상을 청구할 수 있습니다.","6월 전 양도도 그 뒤 6월이 지나도록 주권이 발행되지 않으면 하자가 치유된다":"주권 발행 전 양도의 하자는 6월 뒤에도 주권이 안 나오면 치유됩니다.","가처분명령에 다른 정함이 있거나 법원 허가를 얻은 경우 외에는 상무만 할 수 있으나 위반해도 회사는 선의의 제3자에게 책임진다":"직무대행자는 가처분명령에 다른 정함이 있거나 법원 허가가 있는 경우를 빼면 상무만 할 수 있고, 위반해도 선의의 제3자에게는 회사가 책임집니다.","각 발기인은 서면으로 주식을 인수하고 인수가액 전액을 납입 → 이사·감사는 발기인의 의결권(인수주식 1주에 1개) 과반수로 선임 → 변태설립사항이 있으면 이사가 검사인 선임을 법원에 청구하고, 법원의 변경에 불복하는 발기인은 주식인수를 취소할 수 있다 → 자본금 10억원 미만 발기설립은 납입금보관증명서를 잔고증명서로 대신할 수 있다":"발기설립은 인수와 전액 납입 후 이사·감사를 뽑고, 변태설립사항이 있으면 검사인을 청구하며 10억원 미만이면 잔고증명서를 쓸 수 있습니다.","각 주주는 1주마다 선임할 이사 수만큼 의결권을 가지고 최다 득표자부터 선임되며, 청구 서면은 총회 종결 때까지 본점에 비치한다":"집중투표에서는 1주마다 선임할 이사 수만큼 의결권을 가지고 득표 순으로 선임하며 청구 서면은 총회 종결 때까지 본점에 둡니다.","각 회사의 주주·이사·감사·청산인·파산관재인 또는 합병을 승인하지 않은 채권자가 합병등기일부터 6월 내에 소로만 주장한다":"합병무효의 소는 각 회사의 주주·이사·감사·청산인·파산관재인과 승인하지 않은 채권자가 등기일부터 6월 내에 소로만 제기합니다.","감사가 임무를 게을리하면 회사에 손해를 배상하고 이사도 책임이 있으면 연대한다":"임무 해태 감사는 회사에 배상책임을 지고 이사와 함께 책임질 때는 연대합니다.","감사는 주주총회에서 선임하고, 의결권 없는 주식을 뺀 발행주식총수의 3%(정관으로 더 낮출 수 있음)를 넘는 주식은 그 초과분만 의결권을 행사하지 못한다":"감사 선임에서는 3%(정관으로 더 낮출 수 있음)를 넘는 주식은 초과분만 의결권이 제한됩니다.","감사는 회사 및 자회사의 이사·지배인 기타 사용인의 직무를 겸하지 못하지만 자회사의 감사는 겸할 수 있고, 모회사 이사가 자회사 감사를 겸하는 것도 막지 않는다":"감사는 회사와 자회사의 이사·지배인·사용인을 겸할 수 없지만 자회사의 감사는 겸할 수 있습니다.","감사도 서면으로 이사회에 임시총회 소집을 청구할 수 있다":"감사도 서면으로 이사회에 임시총회 소집을 요구할 권한을 갖습니다.","감사위원회의 대표는 독립이사여야 하고, 감사보고서는 총회일 1주 전까지 제출할 수 있다":"대표는 독립이사 가운데서 정해야 하고, 감사보고서는 총회일 1주 전까지만 내면 됩니다.","같은 지역에서 동종영업으로 타인의 등기 상호를 쓰면 부정한 목적이 추정된다":"동종영업을 같은 지역에서 하며 남이 등기한 상호를 쓰면 부정한 목적이 있다고 추정됩니다.","거래소 시세가 있는 물건은 직접 매도인·매수인이 되는 개입권이 있다":"위탁매매인은 거래소 시세가 있는 물건에 한해 스스로 상대방이 되어 거래하는 개입권을 가집니다.","거절증서나 선언은 제시기간이 지나기 전에 작성시키고 말일에 제시했으면 다음 제1거래일에 작성시킬 수 있다":"거절을 증명하는 증서나 선언은 제시기간이 끝나기 전에 작성하게 하되, 말일에 제시했다면 다음 제1거래일까지 가능합니다.","거절증서 날짜(무비용상환이면 만기일)부터 1년":"소지인의 배서인·발행인에 대한 청구권은 거절증서 날짜(무비용상환은 만기)부터 1년이 지나면 시효로 소멸합니다.","결손 보전을 위한 감소는 보통결의로 하고 채권자보호절차도 필요 없다":"결손 보전 목적의 감자는 보통결의로 하며 채권자보호절차도 필요 없습니다.","결의내용이 법령에 위반하면 제기한다":"결의내용이 법령에 위반하면 결의무효확인의 소를 제기합니다.","결의는 출석 의결권 3분의 2 이상과 사채 총액 3분의 1 이상으로 하고 법원 인가를 받아야 효력이 생기되 그 종류 사채권자 전원이 동의한 결의는 인가 없이 효력이 있다":"사채권자집회는 출석 의결권의 3분의 2 이상과 총액의 3분의 1 이상으로 결의하고 법원 인가가 있어야 효력이 생깁니다.","결의사항이 등기된 경우 판결이 확정되면 본점 소재지에서 등기한다":"결의사항이 등기된 경우에는 확정판결 뒤 본점 소재지에서 그 판결 내용을 등기합니다.","결의일부터 2년 이상 재임·재직해야 행사하고, 양도할 수 없으나 상속인은 행사할 수 있으며 신주 발행 시 행사가액은 부여일 기준 실질가액과 권면액 중 높은 금액 이상이다":"선택권은 결의일부터 2년 이상 재임해야 행사하고 상속은 가능하나 양도는 안 되며, 신주 행사가액은 실질가액과 권면액 중 높은 쪽 이상입니다.","경업금지를 약정하면 같은 지역에 한하여 20년을 넘지 않는 범위에서 효력이 있다":"물건판매 점포의 사용인은 판매에 관해서는 모든 권한이 있는 것으로 봅니다.","계산서를 승인하면 착오나 탈루가 없는 한 각 항목에 이의하지 못한다":"상호계산에서 계산서를 승인하면 착오나 탈루가 없는 한 각 항목에 이의를 제기할 수 없습니다.","계약이 성립하면 결약서를 작성해 각 당사자에게 교부하고, 이 절차를 마치지 않으면 보수를 청구하지 못한다":"중개인은 계약이 성립하면 결약서를 작성해 교부해야 하며 이를 마치지 않으면 보수를 청구할 수 없습니다.","고객이 종류와 가액을 명시하여 임치하지 않으면 책임이 없다":"고객이 종류와 가액을 밝혀 임치하지 않은 고가물에 대해서는 공중접객업자의 책임이 없습니다.","고의·과실로 법령·정관에 위반하거나 임무를 게을리한 이사는 회사에 연대하여 배상하고, 이사회 결의에 참가해 의사록에 이의를 적지 않은 이사는 찬성한 것으로 추정한다":"법령·정관 위반이나 임무 해태 이사는 회사에 연대 배상하며, 의사록에 이의를 적지 않은 참석 이사는 찬성한 것으로 추정합니다.","고의·중과실, 경업, 사업기회 유용, 자기거래에는 적용하지 않는다":"고의·중과실, 경업, 사업기회 유용, 자기거래는 면제 특례의 적용을 받지 못합니다.","고의·중과실이 있을 때 지고, 업무집행지시자·명예회장 등은 이사로 보아 연대책임을 진다":"고의·중과실이 있을 때 이사로서 책임지고, 업무집행지시자와 명예회장도 이사로 의제돼 연대책임을 집니다.","공고·통지일부터 2주 이내에 서면으로 반대한 주주는 그 기간이 지난 날부터 20일 이내에 매수를 청구할 수 있다":"간이 영업양도에서 공고·통지일부터 2주 안에 서면으로 반대한 주주는 그 기간이 지난 날부터 20일 안에 매수를 청구합니다.","공동대표이사에 대한 제3자의 의사표시는 1인에게 하면 효력이 있다":"공동대표이사에게 하는 상대방의 의사표시는 그중 한 명에게만 해도 효력이 있습니다.","공동지배인에게 하는 의사표시는 지배인 1인에게 해도 영업주에게 효력이 있다":"공동지배인이 여럿일 때도 상대방의 의사표시는 그중 한 명에게만 해도 영업주에게 효력이 있습니다.","공중접객업자는 임치받지 않은 휴대물도 자기나 사용인의 과실로 멸실·훼손되면 배상하고, 책임이 없음을 알렸어도 면하지 못한다":"공중접객업자는 맡지 않은 휴대물도 본인이나 사용인의 과실로 손해가 나면 배상하며 책임이 없다고 알려도 면하지 못합니다.","공중접객업자의 책임은 6개월이 지나면 시효로 소멸":"공중접객업자는 6개월이 지나면 시효로 책임을 면합니다.","교환무효의 소는 교환일부터 6월 내에 제기하고 판결은 장래효만 있다":"교환무효의 소는 교환일부터 6월 안에 내고 판결은 앞으로만 효력이 있습니다.","국내수표는 발행지가 없어도 유효하고 발행일란이 비어도 수표면 다른 곳에 일정한 날이 적혀 있으면 그날을 발행일로 본다":"국내수표는 발행지 없이도 효력이 있고, 발행일란이 비어도 수표면의 다른 곳에 적힌 날을 발행일로 봅니다.","국내에서 발행하고 지급할 수표는 10일 내에 지급제시하고 이 기간은 수표에 적힌 발행일부터 계산한다(제29조)":"국내 발행·지급 수표는 발행일부터 10일 안에 지급제시하며 기간은 수표에 적힌 발행일을 기준으로 셉니다.","권리 소멸 당시 원인채권이 있었다면 그 뒤 원인채권이 소멸해도 이득상환청구권은 생기지 않고 선의취득으로 권리를 잃은 자나 보충되지 않은 백지어음의 소지인에게도 생기지 않는다":"원인채권이 존재하던 때 권리가 소멸했다면 이득상환청구권이 생기지 않으며, 선의취득으로 잃은 자와 미보충 백지어음 소지인도 마찬가지입니다.","권리이전적 효력이 없고 피배서인이 한 배서는 대리를 위한 배서의 효력만 있으며 어음채무자는 소지인이 해할 것을 알고 취득한 경우가 아니면 배서인에 대한 인적 항변으로 대항하지 못한다":"입질배서에는 권리이전 효력이 없고 피배서인의 배서는 대리배서 효력만 있으며 채무자는 해할 것을 알고 취득한 때가 아니면 인적 항변을 못 합니다.","그 약정만 무효이고 정관 전체가 무효가 되지는 않는다":"변태설립사항을 정관에 적지 않으면 그 약정만 무효이고 정관 전체가 무효가 되지는 않습니다.","금액을 글자와 숫자로 적어 차이가 나면 글자로 적은 금액, 같은 방식으로 중복해 적어 차이가 나면 최소금액이 어음금액이다":"금액이 글자와 숫자로 다르면 글자 금액이, 같은 방식으로 중복해 달라지면 최소금액이 어음금액입니다.","기간 중의 휴일은 기간에 산입하고 말일이 휴일이면 다음 제1거래일까지 늘어나며 선일자수표의 제시기간과 시효도 적힌 발행일을 기준으로 한다":"기간 안 휴일은 산입하며 말일이 휴일이면 다음 거래일까지 연장되고, 선일자수표는 적힌 발행일로 제시기간과 시효를 셉니다.","기명식에 「또는 소지인에게」를 적거나 수취인을 적지 않으면 소지인출급식으로 보아 교부만으로 양도한다":"기명식에 소지인 문구가 붙거나 수취인을 안 쓰면 소지인출급식으로 보아 교부만으로 양도됩니다.","기명식이어도 배서로 양도할 수 있고 이와 상환하지 않으면 운송물 인도를 청구하지 못한다":"기명식이라도 배서로 양도 가능하며, 증권 없이는 운송물 인도를 청구하지 못합니다.","기명은 본명이 아니어도 되고 아호·예명도 쓸 수 있으며 기명과 날인의 명의가 달라도 된다":"기명은 본명이 아니어도 아호·예명이면 되고, 기명과 날인의 명의가 달라도 유효합니다.","기존 채무에 관하여 어음을 주고받으면서 명시적 합의가 없으면 지급을 위하여 발행한 것으로 추정하므로 원인채무는 소멸하지 않는다":"기존 채무에 어음을 받으면서 명시 합의가 없으면 지급을 위한 것으로 추정되어 원인채무가 소멸하지 않습니다.","기한후배서로 권리가 이전되는 데 통지·승낙 같은 대항요건은 필요 없지만 인적 항변이 절단되지 않고 선의취득도 없다":"기한후배서에는 대항요건이 필요 없지만 인적 항변이 끊기지 않고 선의취득도 없습니다.","기한후배서인지는 문면의 일자가 아니라 실제 배서한 날로 정하고 날짜 없는 배서는 작성기간이 지나기 전에 한 것으로 추정한다":"기한후배서는 어음에 적힌 일자가 아닌 실제로 배서한 날을 기준으로 가립니다.","납입기일까지 납입하지 않은 인수인은 최고 없이 당연히 권리를 잃고, 납입한 인수인은 납입기일의 다음 날부터 주주가 된다":"납입기일을 넘긴 인수인은 최고 없이 바로 권리를 잃고, 납입한 인수인은 다음 날 주주가 됩니다.","납입·현물출자가 덜 된 것이 성립 후 드러나면 성립 당시의 사원·이사·감사가 연대하여 지급한다":"납입·현물출자 부족이 성립 후 드러나면 성립 당시의 사원·이사·감사가 연대해 부족분을 지급합니다.","내부관계에는 정관이나 상법에 다른 규정이 없으면 합명회사 규정을 준용하고 사원총회가 없어 정기총회 소집의무도 없다":"내부관계에는 합명회사 규정을 준용하며 사원총회가 없어 정기총회 소집의무도 없습니다.","다른 약정으로 배제할 수 있다":"상사유치권은 당사자의 다른 약정으로 배제할 수 있습니다.","다른 약정이 없으면 가맹상의 영업지역에서 동일·유사 업종 영업을 하지 못하고 특별한 사유가 없으면 가맹상의 영업양도에 동의해야 한다":"가맹업자는 가맹상 영업지역에서 같은 업종 영업이 금지되고, 가맹상의 영업양도에도 특별한 사유 없이 동의해야 합니다.","다른 약정이 없으면 상대방의 채무불이행에 대하여 이행담보책임을 진다":"위탁매매인은 특약이 없으면 상대방의 채무불이행에 대해 이행담보책임을 집니다.","다른 약정이 없으면 양도인은 10년간 동일한 특별시·광역시·시·군과 인접 지역에서 동종영업을 하지 못한다(제41조 제1항)":"특약이 없으면 영업을 양도한 사람은 10년 동안 같은 시·군 등과 인접 지역에서 동종영업을 할 수 없습니다.","다른 약정이 없으면 영업채권 채무자가 이행하지 않을 때 계약 상대방에게 상환을 청구한다":"채권매입업자는 약정이 없으면 채무자가 이행하지 않을 때 영업채권을 판 거래 상대방에게 상환을 청구합니다.","다른 회사의 무한책임사원이 되지 못하지만 주주, 유한책임사원, 유한책임회사의 업무집행자는 될 수 있다":"회사가 맡을 수 없는 지위는 다른 회사의 무한책임사원이고, 주주·유한책임사원·업무집행자는 가능합니다.","다만 자기 성명이나 상호를 영업자의 상호로 쓰게 하면 그 이후 채무에 대하여 영업자와 연대책임을 진다":"다만 익명조합원이 자기 성명이나 상호를 쓰게 하면 그 이후 채무에 대해 영업자와 연대책임을 집니다.","담보를 위하여 발행한 경우 채권자는 원인채권과 어음채권 중 어느 것을 먼저 행사해도 된다":"담보 목적 발행이라면 채권자는 원인채권과 어음채권 어느 쪽을 먼저 행사해도 무방합니다.","당사자 일방의 성명을 표시하지 않은 중개인은 상대방에게 이행책임을 진다":"당사자 한쪽의 성명을 알리지 않은 중개인은 상대방에게 이행책임을 집니다.","당사자 한쪽에게만 상행위여도 전원에게 상법을 적용한다(제3조)":"당사자 한쪽만 상행위를 했어도 양쪽 모두에게 상법이 적용됩니다.","대리권 없이 대리인으로 기명날인한 자는 어음상 책임을 지고 어음금을 지급하면 본인과 같은 권리를 가지며(제8조) 표현대리가 성립하면 소지인은 본인과 무권대리인 모두에게 청구할 수 있다":"대리권 없이 대리인으로 기명날인한 사람은 어음상 책임을 지고 표현대리가 성립하면 소지인은 본인과 무권대리인 모두에게 청구할 수 있습니다.","대리권 제한은 선의의 제3자에게 대항하지 못한다":"지배인의 대리권에 제한을 두어도 선의의 제3자에게는 대항할 수 없습니다.","대리상은 상업사용인이 아니면서 일정한 상인을 위하여 상시 그 영업부류의 거래를 대리하거나 중개하는 자다":"상업사용인이 아닌 독립 상인으로, 특정 상인의 영업부류 거래를 상시 대리하거나 중개하는 사람이 대리상입니다.","대리상의 활동으로 새 고객이나 거래 증가가 생겨 계약 종료 후에도 본인이 이익을 얻으면 대리상은 상당한 보상을 청구할 수 있다":"대리상의 활동으로 늘어난 고객이나 거래가 계약 종료 뒤에도 본인에게 이익이 되면 대리상은 보상을 청구할 수 있습니다.","대리인은 대리권을 증명하는 서면 또는 전자문서를 총회에 제출하고, 판례상 서면은 원본이어야 한다":"대리 행사에는 대리권을 증명하는 서류를 총회에 내야 하며, 판례는 원본일 것을 요구합니다.","대세효가 있으나 소급효가 없어 확정 전의 법률관계는 유지되고, 패소한 원고는 악의 또는 중대한 과실이 있을 때만 회사에 연대하여 배상한다":"설립무효 판결은 대세효가 있으나 소급효가 없어 확정 전 법률관계는 유지되고, 패소 원고는 악의나 중대한 과실이 있을 때만 배상합니다.","대세효와 소급효가 있어 설립·합병·분할·신주발행 무효판결과 달리 확정 전의 법률관계에도 미친다":"감자무효 판결은 설립·합병·분할·신주발행 무효판결과 달리 확정 전 법률관계에도 미치는 소급효가 있습니다.","대표는 위원회가 스스로 결의로 정하고, 이사회가 위원을 해임하려면 이사 총수의 3분의 2 이상의 결의가 필요하며 해임되어도 이사직은 남는다":"감사위원회 대표는 위원회가 스스로 정하며, 위원 해임은 이사 총수 3분의 2 이상의 이사회 결의가 필요하고 해임돼도 이사직은 유지됩니다.","대표 업무집행자의 업무상 불법행위에는 회사가 연대책임을 진다":"대표 업무집행자가 업무상 불법행위를 하면 회사도 함께 연대책임을 집니다.","대표이사는 이사회가 선정하고 정관으로 주주총회에서 선정하게 할 수 있으며 영업에 관한 재판상·재판외의 모든 행위를 한다":"이사회가 대표이사를 선정하는 것이 원칙이고, 정관으로 총회 선정도 가능하며 대표이사는 영업상 모든 재판상·재판외 행위를 합니다.","대표이사를 두지 못하고 이사회가 집행임원과 대표집행임원을 선임하고, 집행임원 임기는 정관에 다른 규정이 없으면 2년을 넘지 못하며 3개월에 1회 이상 이사회에 보고한다":"집행임원 설치회사는 대표이사 대신 이사회가 대표집행임원을 선임하고, 집행임원 임기는 2년을 넘지 못하며 3개월에 1회 이상 이사회에 보고합니다.","대표이사 선정·신주발행·준비금 자본전입·전환사채 발행은 정관으로 주주총회 권한으로 할 수 있다":"대표이사 선정, 신주발행, 준비금 자본전입, 전환사채 발행은 정관에 정하면 주주총회가 결정할 수 있습니다.","대화자 간의 청약은 상대방이 즉시 승낙하지 않으면 효력을 잃는다":"대화자 사이의 청약은 상대방이 즉시 승낙하지 않으면 효력이 없어집니다.","두 경우 모두 채권자보호절차는 거친다":"간이합병과 소규모합병 모두 채권자보호절차는 생략하지 않습니다.","등기 전에는 선의의 제3자에게 대항하지 못하고, 고의·과실로 사실과 다르게 등기한 자는 그 다름을 선의의 제3자에게 대항하지 못한다":"등기 전에는 선의의 제3자에게 대항하지 못하고, 사실과 다르게 등기한 사람은 선의의 제3자에게 그 다름을 주장하지 못합니다.","등기할 사항은 영업소(회사는 본점) 소재지 관할 법원의 상업등기부에 등기하고, 2024.9.20 개정으로 지점 소재지 등기(제35조·제38조)는 삭제되었다":"등기는 영업소 소재지 관할 법원의 상업등기부에 하며, 2024.9.20 개정으로 지점 소재지 등기 규정이 삭제되었습니다.","만기가 공휴일이어도 시효는 만기일 다음 날부터 기산하고 시효의 중단은 그 사유가 생긴 자에 대하여만 효력이 있다":"시효는 만기가 공휴일이어도 만기일 다음 날부터 세고, 중단은 중단 사유가 생긴 채무자에 대해서만 미칩니다.","만기가 없으면 일람출급, 지급지가 없으면 지급인 명칭에 부기한 지, 발행지가 없으면 발행인 명칭에 부기한 지로 보며(제2조) 약속어음은 지급지가 없으면 발행지를 지급지로 본다":"만기가 없으면 일람출급, 지급지·발행지가 없으면 각각 명칭에 부기한 지로 보고, 약속어음은 발행지를 지급지로 봅니다.","만기에 지급이 거절되면 소지인은 배서인·발행인 등에게 상환청구하고 인수의 전부나 일부가 거절되거나 지급인이 파산한 때에는 만기 전에도 할 수 있다":"만기에 지급이 거절되면 상환청구를 하며, 인수 거절이나 지급인 파산이 있으면 만기 전에도 할 수 있습니다.","매도인이 악의이면 이 통지의무가 적용되지 않는다":"매도인이 악의이면 매수인의 검사·통지 의무가 적용되지 않습니다.","매수인은 수령 후 지체 없이 검사하여 하자·수량부족을 즉시 통지해야 한다":"매수인은 물건을 받은 뒤 지체 없이 검사해 하자나 수량 부족을 즉시 통지해야 합니다.","모집설립이 없고 정관은 자본금 규모와 관계없이 공증인 인증으로 효력이 생기며 사원의 성명·주민등록번호·주소를 정관에 적는다":"유한회사는 모집설립이 없고 정관을 자본금과 상관없이 공증인이 인증하며 사원 인적사항을 정관에 적습니다.","목적, 상호, 발행할 주식의 총수, 액면주식 1주의 금액, 설립 시 발행 주식총수, 본점 소재지, 공고 방법, 발기인의 성명·주민등록번호·주소이고 발기인 전원이 기명날인 또는 서명한다(제289조)":"정관에는 목적·상호·발행 주식 총수·액면금액·본점·공고 방법·발기인 사항 등이 반드시 있어야 하고 발기인 모두가 서명합니다.","목적사항에 주주 전원이 서면으로 동의하면 서면결의가 있는 것으로 본다(과반수 동의로는 안 된다)":"서면결의는 목적사항에 주주 전원이 서면으로 동의해야 인정되고 과반수 동의로는 안 됩니다.","무비용상환 문구가 있으면 지급제시기간이 지난 소지인은 배서인·발행인에 대한 권리를 잃지만 인수인에 대한 권리는 잃지 않는다":"무비용상환 문구가 있는 어음은 제시기간 뒤에도 인수인에 대한 권리만은 남고 배서인·발행인에 대한 권리는 잃습니다.","무인(지장)은 날인이 아니고 법인은 대표기관이 법인을 위한다는 뜻을 표시하고 기명날인해야 하므로 법인 명칭과 법인 인감만 찍은 어음은 무효다":"지장은 날인이 아니며, 법인 어음은 대표기관이 법인을 위한다는 뜻과 함께 기명날인해야 해서 법인 명칭과 인감만 찍으면 무효입니다.","무한책임사원 또는 유한책임사원 전원이 퇴사하면 해산하고, 남은 사원 전원의 동의로 빠진 쪽 사원을 새로 가입시켜 계속할 수 있다":"합자회사는 한쪽 책임 사원이 전부 퇴사하면 해산하되 남은 사원 전원 동의로 새 사원을 가입시켜 계속할 수 있습니다.","무한책임사원은 정관에 다른 정함이 없으면 각자 업무를 집행하고, 지배인 선임·해임은 업무집행사원이 있어도 무한책임사원 과반수로 하며 청산인도 무한책임사원 과반수로 선임한다":"무한책임사원이 각자 업무를 집행하며 지배인과 청산인 선임은 업무집행사원이 있어도 무한책임사원 과반수가 합니다.","무한책임사원이 유한책임사원이 되면 변경등기 전 채무에 대하여 등기 후 2년 내에는 무한책임을 진다":"무한에서 유한책임사원이 되어도 변경등기 전 채무에 대해서는 등기 후 2년 동안 무한책임이 남습니다.","무효판결이 확정되면 완전모회사는 발행한 주식의 주주에게 완전자회사 주식을 돌려준다":"이전 무효판결이 확정되면 완전모회사는 주주에게 완전자회사 주식을 반환합니다.","물건을 수령함과 동시에 리스료를 지급하고, 공급이 계약대로 되지 않으면 공급자에게 직접 손해배상이나 인도를 청구하며 중대한 사정변경이 있으면 3개월 전에 예고하고 해지할 수 있다":"금융리스이용자는 물건을 받으면 리스료를 내고, 공급에 하자가 있으면 공급자에게 직접 청구하며 중대한 사정변경 때는 3개월 전 예고로 해지합니다.","물건판매점포의 사용인은 판매에 관한 모든 권한이 있는 것으로 보되 상대방이 악의이면 그렇지 않다":"판매점포 사용인은 판매 권한이 있다고 보지만 상대방이 악의이면 인정되지 않습니다.","미성년자가 법정대리인의 허락을 얻어 영업하면 등기하여야 하고, 허락을 얻어 무한책임사원이 되면 사원자격으로 한 행위에는 능력자로 본다":"미성년자 영업은 법정대리인의 허락과 등기가 있어야 하고, 무한책임사원이 되면 그 사원 행위에서는 성년자로 취급합니다.","미완성으로 발행한 어음에 미리 합의한 내용과 다르게 보충되어도 발행인은 악의·중과실 없는 소지인에게 합의 위반으로 대항하지 못한다(제10조)":"미완성 어음을 합의와 다르게 보충해도 악의·중과실이 없는 소지인에게 발행인은 합의 위반을 내세울 수 없습니다.","반대주주는 의결권이 없거나 제한되는 주주를 포함하며 총회 전에 서면으로 반대 의사를 통지 → 결의일부터 20일 이내에 서면으로 매수를 청구 → 회사는 매수청구기간이 끝나는 날부터 2개월 이내에 매수 → 가격은 협의로 정하고 30일 이내에 협의가 안 되면 회사나 주주가 법원에 결정을 청구":"주식매수청구는 총회 전 서면 반대 통지와 결의 후 20일 내 청구가 요건이고, 회사는 2개월 내 매수하며 가격은 협의 불발 시 법원이 정합니다.","반대주주 매수청구권은 일반 교환과 간이교환에 있고 소규모교환에는 없다":"주식교환의 반대주주 매수청구권은 일반·간이교환에는 있으나 소규모교환에는 없습니다.","발기인의 특별이익, 현물출자, 재산인수(성립 후 양수할 재산의 종류·수량·가격·양도인 성명), 설립비용과 발기인 보수액은 정관에 적어야 효력이 있다(제290조)":"발기인의 특별이익, 현물출자, 재산인수, 설립비용·발기인 보수는 정관에 적어야 효력이 있는 변태설립사항입니다.","발기인이었던 자, 현물출자자, 재산인수 당사자인 이사·감사는 설립 조사·보고에 참가하지 못한다":"설립 조사·보고에는 발기인이었던 자, 현물출자자, 재산인수 당사자인 이사·감사가 참여할 수 없습니다.","발행가액의 2분의 1 이상으로서 이사회(주주총회가 신주발행을 정하는 회사는 주주총회)가 자본금으로 계상하기로 한 금액의 총액이다":"무액면주식 회사의 자본금은 발행가액의 2분의 1 이상으로서 이사회가 자본금으로 정한 금액의 총액입니다.","발행인·배서인·보증인은 무비용상환이나 거절증서 불필요 문구를 적고 기명날인하거나 서명해 거절증서 작성을 면제할 수 있지만 소지인의 법정기간 내 제시·통지 의무는 면제되지 않는다":"발행인·배서인·보증인은 무비용상환 문구로 거절증서 작성을 면제할 수 있으나 소지인의 법정기간 내 제시·통지 의무는 면제되지 않습니다.","발행인으로 기명날인해 외관을 갖춘 어음이 도난 등으로 의사와 관계없이 유통되었더라도 발행인은 선의의 취득자에게 대항하지 못한다":"도난 어음이라도 발행인이 서명해 외관이 갖춰져 있으면 선의 취득자에게는 교부흠결을 주장할 수 없습니다.","발행인은 지급을 담보하고 지급무담보 문구는 적지 않은 것으로 보며(제12조) 금액 기재 차이는 어음과 같이 글자 우선, 중복 기재는 최소금액이다(제9조)":"수표 발행인은 지급을 담보하고 지급무담보 문구는 무효이며, 금액이 다르면 글자 금액이, 중복 기재가 다르면 최소금액이 기준입니다.","발행인은 피융통자에게는 어음상 책임을 지지 않지만 그 어음을 취득한 제3자에게는 융통어음이라는 사실을 알았는지와 관계없이 대항하지 못한다":"발행인은 피융통자에게는 책임이 없으나, 어음을 취득한 제3자에게는 융통어음임을 알았는지와 상관없이 책임집니다.","발행인이나 소지인은 수표 앞면에 두 줄의 평행선을 그을 수 있고 안에 아무것도 없거나 「은행」을 적으면 일반횡선, 은행 명칭을 적으면 특정횡선이다":"앞면에 두 줄의 평행선을 그어 안이 비었거나 은행이라고 적으면 일반횡선, 은행 명칭을 적으면 특정횡선입니다.","발행인이 적은 문구는 모든 어음채무자에게 효력이 있고 그런데도 소지인이 거절증서를 작성시키면 비용은 소지인이 부담한다":"발행인이 기재한 면제 문구는 모든 채무자에게 미치며, 그래도 소지인이 거절증서를 만들게 하면 비용은 소지인 몫입니다.","발행주식총수의 3% 이상 주주는 목적사항과 소집 이유를 적은 서면으로 이사회에 임시총회 소집을 청구하고, 지체 없이 절차를 밟지 않으면 법원의 허가를 받아 직접 소집한다":"3% 이상 주주는 서면으로 소집을 청구하고, 이사회가 응하지 않으면 법원 허가로 스스로 소집합니다.","발행주식총수의 4분의 1을 넘지 못한다(초과해도 당연무효가 아니라 지체 없이 시정 조치)":"의결권 배제·제한 주식은 발행주식총수의 4분의 1을 넘지 못하고, 넘어도 당연무효는 아니며 지체 없이 시정해야 합니다.","발행주식총수의 95% 이상을 가진 지배주주는 주주총회 승인을 받아 소수주주에게 매도를 청구하고, 소수주주는 2개월 내에 매도하며 대금을 지급한 때 주식이 이전된다":"지배주주는 발행주식총수의 95% 이상을 갖고 총회 승인을 받아 소수주주에게 매도를 청구하며, 대금을 지급하면 주식이 넘어옵니다.","발행 후 발행인이 사망하거나 무능력자가 되어도 수표의 효력에는 영향이 없다(제33조)":"발행 후 발행인이 사망하거나 무능력자가 되어도 수표의 효력은 그대로입니다.","배당은 종류주식이 아니면 주식 수에 따르고 결의일부터 1개월 내에 지급하며 지급청구권은 5년의 시효로 소멸한다":"종류주식이 아니면 주식 수에 비례해 배당하고, 결의 후 1개월 내에 지급하며 청구권은 5년이면 소멸합니다.","배서에 붙인 조건은 적지 않은 것으로 보고 일부의 배서는 무효이며 소지인출급 배서는 백지식 배서와 같다":"배서 조건과 일부 배서는 효력이 없고, 소지인출급 배서는 백지식 배서로 취급합니다.","배서에 붙인 조건은 적지 않은 것으로 보고 일부의 배서는 무효이며 지급인의 배서는 무효, 지급인에게 한 배서는 영수증의 효력만 있다":"수표의 배서 조건과 일부 배서, 지급인의 배서는 무효이고 지급인에게 하는 배서는 영수증 효력만 가집니다.","배서의 연속으로 권리를 증명하면 적법한 소지인으로 추정하고 말소한 배서는 연속에 관하여 배서하지 않은 것으로 보며 절취자가 말소한 경우도 같다":"배서 연속이 있으면 적법한 소지인으로 추정하고, 말소된 배서는 연속에서 없는 것으로 보며 절취자가 지워도 같습니다.","배서인은 반대 문구가 없으면 인수와 지급을 담보하고 무담보배서인은 모든 후자에게 책임이 없으나 배서금지배서인은 직접 피배서인에게는 담보책임을 진다":"배서인은 인수·지급을 담보하지만 무담보배서인은 후자에게 면책되고 배서금지배서인은 직접 피배서인에게만 담보책임이 있습니다.","백지어음도 선의취득 대상이고 보충할 때 보충자의 기명날인은 필요 없다":"백지어음도 선의취득이 가능하며 보충하는 사람의 서명·날인은 필요하지 않습니다.","백지어음이 아니라 요건이 빠진 불완전어음이라서 무효라는 점은 발행인이 증명한다":"요건이 빠져 무효라는 불완전어음 주장은 백지어음과 달리 발행인이 증명해야 합니다.","법령·정관에 위반하거나 현저하게 불공정한 방법으로 신주를 발행해 불이익을 받을 염려가 있는 주주는 회사에 발행 유지를 청구할 수 있다":"법령·정관을 어기거나 불공정한 신주 발행으로 불이익을 입을 주주는 회사에 발행 유지를 청구할 수 있습니다.","법원은 결의 내용, 회사 현황 등을 참작해 재량기각할 수 있고 인용판결은 대세효와 소급효가 있다":"법원이 재량기각을 할 수 있다는 점과 인용 판결에 대세효·소급효가 있다는 점이 결의취소의 소의 특징입니다.","법원이 선임한 경우 외에는 주주총회 보통결의로 언제든지 해임하고, 현저히 부적임하면 3% 이상 주주가 법원에 해임을 청구한다":"청산인은 보통결의로 언제든 해임하고, 현저히 부적임하면 3% 이상 주주가 법원에 해임을 청구합니다.","법정대리인의 대리권 제한은 선의의 제3자에게 대항하지 못한다":"법정대리인의 대리권이 제한되어 있어도 이를 모르는 제3자에게는 주장하지 못합니다.","법정대리인이 미성년자·피한정후견인·피성년후견인을 위하여 영업할 때도 등기한다":"법정대리인이 제한능력자를 위해 영업하는 경우에도 그 사실을 등기해야 합니다.","변경등기일부터 1년이 지나면 인수인은 청약서 요건 흠결을 이유로 무효를 주장하지 못한다":"변경등기일부터 1년이 지나면 청약서 요건 흠결을 이유로 한 무효 주장은 할 수 없습니다.","변경등기 후 인수되지 않은 주식이나 청약이 취소된 주식은 이사가 공동으로 인수한 것으로 본다":"변경등기 뒤에도 인수되지 않았거나 청약이 취소된 주식은 이사가 함께 인수한 것으로 봅니다.","변태설립사항이 아니라 주주총회 특별결의 사항이다":"사후설립은 변태설립사항으로 정관에 적는 것이 아니라 주주총회 특별결의로 처리합니다.","보수는 당사자 쌍방이 균분하여 부담한다":"중개인의 보수는 당사자 양쪽이 똑같이 나누어 부담합니다.","보증이 상행위이거나 주채무가 상행위로 인한 것이면 주채무자와 보증인이 연대한다":"보증이 상행위이거나 주채무가 상행위에서 생기면 보증인도 주채무자와 연대합니다.","보통결의는 출석 의결권의 과반수와 발행주식총수의 4분의 1 이상":"보통결의는 출석 의결권의 과반수와 발행주식총수의 4분의 1 이상이라는 두 요건을 모두 갖춰야 합니다.","본부장·지점장 등 지배인으로 인정될 명칭을 쓰는 자는 지배인과 같은 권한이 있는 것으로 보지만 재판상 행위는 제외되고 상대방이 악의이면 적용하지 않는다":"본부장·지점장 같은 명칭을 쓰면 재판상 행위를 뺀 지배인 권한이 인정되나, 상대방이 악의이면 적용하지 않습니다.","본인을 위하여 점유하는 물건이면 되고 본인 소유일 필요가 없다":"대리상의 유치권은 본인을 위해 점유하는 물건이면 되고 본인 소유일 필요가 없습니다.","본인의 허락 없이 영업부류 거래를 하거나 동종영업 회사의 무한책임사원·이사가 되지 못한다":"대리상이 본인 허락 없이 영업부류 거래를 하거나 동종 회사의 무한책임사원·이사가 되면 경업금지 위반입니다.","분할계획서에 따라 권리의무를 승계하고, 분할회사의 출자만으로 설립되면 검사인 조사가 필요 없으며 분할회사의 자기주식에는 신주를 배정하지 못한다":"신설회사는 분할계획서로 권리의무를 승계하며, 분할회사만 출자하면 검사인 조사가 불필요하고 분할회사 자기주식에는 신주를 못 줍니다.","분할·분할합병은 주주총회 특별결의로 승인하고 이 결의에서는 의결권이 배제되는 주주도 의결권이 있고, 주주의 부담이 가중되면 그 주주 전원의 동의가 필요하다":"분할은 특별결의 승인 사항이고 의결권 배제 주주도 의결하며, 주주 부담이 늘면 그 주주 전원의 동의가 필요합니다.","분할회사와 분할승계회사가 각각 채권자보호절차를 거친다":"분할합병은 두 회사가 각각 채권자보호절차를 밟습니다.","분할 후 회사들은 분할 전 채무에 대하여 연대책임을 지는 것이 원칙이다":"분할 후 각 회사는 분할 전 채무에 연대해서 책임지는 것이 기본입니다.","사업기회 유용으로 얻은 이익은 회사의 손해로 추정한다":"사업기회 유용으로 이사가 얻은 이익은 회사가 입은 손해로 추정됩니다.","사업기회 이용과 이사·주요주주 및 그 배우자·직계존비속 등의 자기거래는 이사 3분의 2 이상의 승인이 필요하다":"사업기회 이용과 이사·주요주주 및 그 가족 등과의 자기거래는 이사 3분의 2 이상의 승인을 받아야 합니다.","사원 1인으로 설립할 수 있고 사원은 금전 기타 재산으로만 출자하며(신용·노무 불가) 설립등기 때까지 출자를 전부 이행한다":"유한책임회사는 사원 1인으로 설립할 수 있고 금전 등 재산만 출자하며 설립등기 때까지 출자를 모두 이행해야 합니다.","사원은 지분 요건 없이 업무집행자의 책임을 추궁하는 소의 제기를 청구할 수 있다":"유한책임회사 사원은 지분 요건 없이 업무집행자 책임을 묻는 소 제기를 청구할 수 있습니다.","사원의 경업·겸직은 다른 사원의 동의, 자기거래는 다른 사원 과반수의 결의가 있어야 하고 사원은 신용·노무도 출자할 수 있다":"경업·겸직에는 다른 사원의 동의, 자기거래에는 다른 사원 과반수 결의가 필요하며 신용·노무 출자도 가능합니다.","사원의 책임은 출자금액을 한도로 한다":"유한책임회사 사원은 출자금액을 한도로만 책임집니다.","사원이 1인으로 되거나 법원의 명령·판결로 해산한 경우에는 임의청산을 하지 못하고, 임의청산도 청산이므로 청산을 거치지 않고 바로 소멸하지 않는다":"사원이 1인이 되거나 법원의 명령·판결로 해산한 경우에는 임의청산을 할 수 없고, 임의청산도 청산이라 바로 소멸하지는 않습니다.","사원이 1인이 되어도 해산하지 않는다":"유한회사는 사원이 1인이 되어도 해산하지 않습니다.","사장·전무 등 명칭을 쓴 표현대표이사의 행위는 선의·무중과실 제3자에게 회사가 책임진다":"사장·전무 같은 직함을 쓴 표현대표이사의 행위는 선의·무중과실의 상대방에게 회사가 책임을 집니다.","사채권자가 이의하려면 사채권자집회의 결의가 있어야 하고 법원은 사채권자를 위해 이의기간을 연장할 수 있다":"감자에 이의하려는 사채권자는 집회 결의가 필요하고 법원은 이의기간을 연장할 수 있습니다.","사채는 이사회 결의로 발행하고 총액을 계약으로 인수하면 사채청약서가 필요 없으며 모집이 끝나면 이사가 전액 또는 제1회 납입을 시키고 채권은 전액 납입 후 발행한다":"사채는 이사회가 발행하고 총액 인수계약이면 청약서가 불필요하며, 모집 뒤 납입을 거쳐야 채권이 발행됩니다.","사채의 인수인은 사채관리회사가 될 수 없고 사채관리회사는 발행회사와 사채권자집회의 동의나 부득이한 사유에 따른 법원 허가로 사임한다":"사채 인수인은 사채관리회사가 될 수 없고, 사임은 발행회사와 사채권자집회 동의나 법원 허가로 합니다.","상속·합병 같은 포괄승계와 기한후배서로 취득한 자에게는 항변이 절단되지 않는다":"포괄승계(상속·합병)와 기한후배서 취득자에게는 인적 항변이 절단되지 않습니다.","상시 거래관계에 있는 자로부터 영업부류의 청약을 받은 상인은 지체 없이 낙부의 통지를 발송하고, 하지 않으면 승낙한 것으로 본다(제53조)":"상시 거래하는 사람의 영업부류 청약을 받은 상인이 지체 없이 낙부를 알리지 않으면 승낙한 것으로 봅니다.","상업사용인은 영업주의 허락 없이 영업부류에 속한 거래를 하거나 다른 회사의 무한책임사원·이사·다른 상인의 사용인이 되지 못한다 → 위반 거래가 자기 계산이면 영업주의 계산으로 볼 수 있고(개입권), 제3자 계산이면 이득의 양도를 청구한다 → 이 권리는 거래를 안 날부터 2주간, 거래가 있은 날부터 1년이 지나면 소멸한다":"상업사용인이 허락 없이 영업부류 거래나 겸직을 하면 영업주가 개입권·이득양도를 청구하며, 안 날부터 2주, 거래일부터 1년이 지나면 소멸합니다.","상업장부와 영업에 관한 중요서류는 10년, 전표류는 5년 보존하고 상업장부 기간은 폐쇄한 날부터 센다":"상업장부의 보존기간은 폐쇄한 날부터 세고, 장부와 중요서류는 10년, 전표류는 5년입니다.","상인 간 매매에서 매수인이 수령을 거부하면 매도인은 공탁하거나 상당한 기간을 정해 최고한 뒤 경매할 수 있다":"매수인이 수령을 거부하면 매도인은 공탁이나 최고 후 경매의 방법을 택할 수 있습니다.","상인 간의 상행위로 생긴 채권이 변제기에 있으면 채권자는 채무자에 대한 상행위로 점유하는 채무자 소유의 물건이나 유가증권을 유치할 수 있다(제58조)":"상인 간 상행위 채권이 변제기에 있으면 채권자는 채무자 소유의 물건이나 유가증권을 유치할 수 있는 상사유치권을 갖습니다.","상인이 영업에 관하여 금전을 대여하면 약정이 없어도 법정이자를 청구한다":"상인이 영업에 관해 금전을 빌려주면 이자 약정이 없어도 법정이자를 청구할 수 있습니다.","상인이 영업에 관하여 준 대리권은 본인의 사망으로 소멸하지 않는다":"상인이 영업에 관해 준 대리권은 민법과 달리 본인이 사망해도 소멸하지 않습니다.","상인이 영업을 위하여 하는 행위는 상행위로 보고, 상인의 행위는 영업을 위한 것으로 추정한다(제47조)":"상인이 영업을 위해 하는 행위는 보조적 상행위가 되고, 상인의 행위는 영업을 위한 것으로 추정됩니다.","상장회사는 이사 총수의 3분의 1 이상을 독립이사로 하고 자산총액 2조원 이상이면 3명 이상·이사 총수의 과반수로 한다":"독립이사는 이사 총수의 3분의 1 이상이어야 하며, 2조원 이상 대규모 상장회사는 3명 이상에 과반수를 채워야 합니다.","상행위나 그 밖의 영리를 목적으로 설립한 법인":"회사는 영리 목적으로 설립된 법인을 말하며 상행위 여부는 필수 요건이 아닙니다.","상행위로 생긴 채권을 담보하는 질권에는 유질계약 금지(민법 제339조)가 적용되지 않는다":"상행위로 생긴 채권을 담보하는 질권에는 유질계약 금지가 적용되지 않아 유질이 허용됩니다.","상행위로 인한 채권은 상법에 다른 규정이 없으면 5년간 행사하지 않으면 소멸시효가 완성되고, 다른 법령에 더 짧은 시효가 있으면 그에 따른다(제64조)":"상행위로 생긴 채권은 달리 규정이 없으면 5년의 소멸시효에 걸리고, 다른 법령에 더 짧은 시효가 있으면 그에 따릅니다.","상행위로 인한 채무의 법정이율은 연 6분이다(제54조)":"상행위로 생긴 채무의 법정이율은 연 6분입니다.","상행위의 대리인은 본인을 위한 것임을 표시하지 않아도 본인에게 효력이 생기고, 상대방이 그 사정을 몰랐으면 대리인에게도 이행을 청구할 수 있다(제48조)":"상행위 대리에서는 본인을 위한 것임을 표시하지 않아도 본인에게 효력이 생기며, 상대방이 몰랐다면 대리인 상대 이행 청구도 가능합니다.","상호는 영업을 폐지하거나 영업과 함께하는 경우에만 양도할 수 있고 양도는 등기해야 제3자에 대항한다":"상호는 영업을 폐지하거나 영업과 함께할 때만 양도할 수 있고, 등기를 해야 제3자에게 대항합니다.","상호를 계속 쓰지 않는 양수인도 양도인의 채무를 인수한다고 광고 → 양수인은 변제할 책임이 있다(제44조) → 양수인이 책임을 지는 경우 양도인의 제3자에 대한 채무는 영업양도 또는 광고 후 2년이 지나면 소멸한다":"상호를 안 쓰는 양수인도 채무인수를 광고하면 변제할 책임이 있고, 양도인의 책임은 양도나 광고 후 2년이 지나면 소멸합니다.","상호를 등기한 자가 정당한 사유 없이 2년간 쓰지 않으면 폐지한 것으로 본다":"상호를 등기한 사람이 정당한 사유 없이 2년 동안 쓰지 않으면 상호를 폐지한 것으로 봅니다.","상호속용 때 채무자가 선의이며 중대한 과실 없이 양수인에게 변제하면 유효하다":"상호를 계속 쓰는 양수인에게 채무자가 선의·무중과실로 변제하면 그 변제가 유효합니다.","상환·전환 외의 종류주식으로만 발행하고 상환 대가로 현금·유가증권·자산을 줄 수 있으나 다른 종류주식은 주지 못한다":"상환주식은 상환·전환 외의 종류주식으로 발행하고 현금·유가증권·자산으로 상환할 수 있으나 다른 종류주식은 줄 수 없습니다.","새 사원은 정관변경 때 가입하되 출자를 이행하지 않았으면 이행한 때 사원이 되고, 퇴사 사원은 지분을 금전으로 환급받는다":"새 사원은 정관변경 때 가입하고 출자를 이행한 때 사원이 되며, 퇴사 사원은 금전으로 지분을 환급받습니다.","서면투표는 정관에 정함이 있어야 하고 전자투표는 이사회 결의로 정하며 같은 주식에 대해서는 둘 중 하나만 선택한다":"서면투표는 정관 근거가, 전자투표는 이사회 결의가 필요하고 같은 주식에는 하나만 고를 수 있습니다.","선의로 취득한 소지인에게 운송인은 증권에 적힌 대로 운송물을 수령한 것으로 보고 책임진다":"증권에 적힌 대로 운송물을 받은 것으로 보아 선의의 소지인에게 운송인이 책임을 집니다.","선임과 대리권 소멸은 영업소(회사는 본점) 소재지에서 등기한다":"영업소 소재지(회사는 본점)에서 지배인의 선임·대리권 소멸을 등기해야 합니다.","설립 때 발행하는 주식의 종류와 수, 액면 이상 발행의 수·금액, 무액면주식의 발행가액과 자본금 계상액은 정관에 정함이 없으면 발기인 전원의 동의로 정한다":"설립 시 발행 주식의 종류·수, 액면 이상 발행, 무액면주식 발행가액 등은 정관에 없으면 발기인 전원의 동의로 정합니다.","설립목적이 불법하거나 정당한 사유 없이 설립 후 1년 내 영업을 개시하지 않거나 1년 이상 휴지하면 법원은 청구 또는 직권으로 해산을 명할 수 있다":"설립목적이 불법이거나 설립 후 1년 안에 영업을 시작하지 않거나 1년 이상 쉬면 법원이 해산을 명할 수 있습니다.","설립무효는 사원만 성립일부터 2년 내에 소로만 주장하며 사해설립취소는 채권자가 사원과 회사를 상대로 제기한다":"합명회사의 설립무효는 사원이 성립일부터 2년 안에 소로 주장하고, 채권자는 사해설립취소를 사원·회사 상대로 냅니다.","설립무효의 소는 사원과 업무집행자가 제기한다":"유한책임회사의 설립무효는 사원과 업무집행자가 소로 주장합니다.","설립취소의 소가 없고, 설립무효는 주주·이사·감사만 회사성립일부터 2년 내에 본점소재지 지방법원에 소로써 주장한다(제328조)":"주식회사는 설립취소의 소가 없고, 설립무효는 주주·이사·감사만 성립일부터 2년 안에 본점 지방법원에 소로 주장합니다.","성립 후 가입한 사원도 가입 전 채무에 같은 책임을 진다":"성립 후 가입한 사원도 가입 전 채무에 대해 다른 사원과 같은 책임을 집니다.","성립 후 인수되지 않은 주식이나 청약이 취소된 주식은 발기인이 공동으로 인수한 것으로 보고, 납입 미완료 주식은 발기인이 연대하여 납입하며 이 담보책임은 총주주의 동의로도 면제되지 않는다":"발기인은 인수되지 않은 주식을 공동 인수한 것으로 보고 납입 미완료 주식을 연대 납입하며 이 책임은 총주주 동의로도 면제되지 않습니다.","성질·법령·정관상 목적에 의하여 제한되어 친권·상속은 누릴 수 없으나 유증은 받을 수 있고 명예권·상호권은 가진다":"회사는 성질상 친권·상속이 불가능하지만 유증은 받을 수 있고 명예권과 상호권을 갖습니다.","소멸회사 반대주주는 매수청구를 할 수 있다":"간이합병에서도 소멸회사 반대주주는 주식매수청구권이 있습니다.","소멸회사의 총주주가 동의하거나 존속회사가 소멸회사 발행주식총수의 90% 이상을 가진 때 소멸회사 총회 승인을 이사회 승인으로 갈음":"간이합병은 소멸회사 총주주가 동의하거나 존속회사가 90% 이상을 가질 때 소멸회사 총회 승인을 이사회 승인으로 갈음합니다.","소멸회사 주주는 할 수 있다":"소규모합병에서도 소멸회사 주주는 주식매수청구를 할 수 있습니다.","소지인은 거절증서 작성일 이후 4거래일 내에 자기의 배서인과 발행인에게 거절을 통지하며 배서인은 받은 날 이후 2거래일 내에 앞의 배서인에게 통지한다":"소지인은 거절증서 작성일 이후 4거래일 내에 통지하고, 배서인은 받은 날 이후 2거래일 내에 앞 배서인에게 통지합니다.","소지인은 일부지급을 거절하지 못하며 만기에 지급하는 지급인은 사기 또는 중대한 과실이 없으면 면책되고 기명날인의 진위까지 조사할 의무는 없다(제40조)":"소지인은 일부지급을 거절할 수 없고, 지급인은 사기·중과실이 없으면 면책되며 기명날인의 진위까지 조사할 의무는 없습니다.","소지인은 일부지급을 거절하지 못하며(제34조) 지급인은 배서의 연속만 조사하고 기명날인까지 조사할 의무는 없다(제35조)":"소지인은 일부지급을 거절하지 못하고, 지급인은 배서의 연속만 조사하며 기명날인의 진위까지 조사할 의무는 없습니다.","소지인의 상환청구권은 제시기간이 지난 후 6개월, 채무자의 재상환청구권은 환수한 날이나 제소된 날부터 6개월의 시효로 소멸한다":"제시기간 후 6개월이 지나면 소지인의 상환청구권이, 환수·제소 후 6개월이 지나면 재상환청구권이 소멸합니다.","소지인출급식 수표에 배서한 자는 상환청구에 관한 책임을 지지만 그 수표가 지시식으로 바뀌지는 않는다":"소지인출급식 수표에 한 배서는 상환청구 책임을 만들지만 수표를 지시식으로 바꾸지는 않습니다.","소집절차·결의방법의 하자가 결의가 존재한다고 볼 수 없을 정도로 중대하면 제기하고 둘 다 제소기간 제한이 없으며 판결에 소급효가 있다":"결의가 있다고 볼 수 없을 정도의 중대한 하자가 있으면 부존재확인의 소이며, 무효·부존재 확인의 소는 제소기간 제한이 없고 소급효가 있습니다.","소집절차·결의방법이 법령·정관에 위반하거나 현저히 불공정한 때와 결의내용이 정관에 위반한 때":"결의취소의 사유는 소집절차·결의방법의 법령·정관 위반이나 현저한 불공정, 그리고 결의내용의 정관 위반입니다.","소집 철회는 이사회 결의를 거쳐 대표이사가 소집과 같은 방법으로 통지한다":"이사회 결의 뒤 대표이사가 소집한 방식 그대로 통지하면 소집을 철회할 수 있습니다.","소집통지는 1주 전에 하고 총사원 동의가 있으면 소집절차 없이 열거나 서면결의를 할 수 있으며, 목적사항에 총사원이 서면으로 동의하면 서면결의가 있는 것으로 본다":"사원총회는 1주 전에 소집하며 총사원 동의가 있으면 소집절차 없이 열거나 서면결의를 할 수 있습니다.","손익은 정관에 정함이 없으면 출자가액에 비례하여 나눈다":"손익 분배는 정관에 정함이 없으면 출자가액에 비례합니다.","수표는 기명식·지시식, 지시금지 기명식, 소지인출급식으로 발행할 수 있다":"수표의 수취인 표시 방식은 기명식·지시식, 지시금지 기명식, 소지인출급식 중에서 고릅니다.","수표는 발행인이 처분할 수 있는 자금이 있는 은행을 지급인으로 하고 수표계약에 따라 발행해야 하지만 이를 어겨도 수표의 효력에는 영향이 없다":"수표는 발행인의 처분 가능한 자금이 있는 은행을 지급인으로 해야 하나, 그 규정을 어겨도 수표 효력은 유지됩니다.","수표는 인수하지 못하고 인수 문구는 적지 않은 것으로 보며(제4조) 이자 약정도 적지 않은 것으로 본다(제7조)":"수표는 인수가 불가능해 인수 문구는 적지 않은 것으로 보고, 이자 약정도 효력이 없습니다.","수표는 일람출급이고 이에 반하는 문구는 적지 않은 것으로 보며 기재된 발행일 전에 제시된 선일자수표도 제시된 날에 지급해야 한다(제28조)":"수표는 일람출급이어서 반대 문구는 효력이 없고, 선일자수표도 제시된 날에 지급해야 합니다.","수표에는 수표 문자, 조건 없는 지급위탁, 지급인, 지급지, 발행일과 발행지, 발행인의 기명날인 또는 서명을 적고 수취인과 만기는 요건이 아니다":"수표에 쓰는 사항은 수표 문자, 지급위탁, 지급인, 지급지, 발행일·지, 서명이며 수취인과 만기는 필요 없습니다.","수하인이 유보 없이 운송물을 수령하고 운임을 지급하면 운송인의 책임이 소멸하되, 즉시 발견할 수 없는 훼손은 수령일부터 2주간 내에 통지하면 유지된다":"수하인이 유보 없이 받고 운임을 지급하면 책임이 소멸하나, 즉시 발견 못 한 훼손은 수령일부터 2주 안에 통지하면 유지됩니다.","시효 완성 전에 어음금 청구의 소를 냈다면 시효기간이 지난 뒤 변론종결 전에 백지를 보충해도 시효중단 효력이 유지된다":"소를 제기해 시효가 중단된 뒤에는 변론종결 전에 백지를 보충해도 중단 효력이 유지됩니다.","신설합병의 정관 작성 등 설립행위는 각 회사가 선임한 설립위원이 공동으로 한다":"설립위원이 신설합병의 정관 작성 등 설립행위를 함께 합니다.","신주인수권 행사로 발행할 주식의 발행가액 합계는 각 사채 금액을 넘지 못하고, 전액을 납입한 때 주주가 되며 대용납입이 아니면 사채는 남는다":"신주인수권을 행사하면 발행가액 합계가 사채 금액 이내여야 하고, 전액 납입 때 주주가 되며 대용납입이 아니면 사채는 남습니다.","액면·무액면 사이의 전환으로는 자본금이 바뀌지 않아 채권자보호절차가 없다":"액면과 무액면 사이 전환은 자본금이 바뀌지 않으므로 채권자보호절차가 필요 없습니다.","액면·무액면 사이의 전환으로 자본금은 바뀌지 않고, 자본금의 액은 설립등기사항이다":"액면과 무액면 사이 전환에서도 자본금은 그대로이며 자본금의 액은 등기사항입니다.","액면주식 1주의 금액은 100원 이상이고 주식 분할은 주주총회 특별결의로 하되 분할 후에도 100원 미만으로 하지 못한다":"액면주식은 1주 금액이 100원 이상이어야 하고 주식분할도 100원 미만이 되면 안 됩니다.","양도인이 무권리자인 경우뿐 아니라 대리권 흠결이나 하자가 있는 경우도 선의취득으로 치유된다고 보고 의심할 사정이 있는데 조사 없이 양수하면 중과실이다":"양도인의 무권리뿐 아니라 대리권 흠결도 선의취득으로 치유되고, 의심할 사정이 있는데도 조사 없이 양수하면 중과실입니다.","양수인이 양도인의 상호를 계속 쓰면 양도인의 영업으로 인한 제3자의 채권에 대하여 양수인도 변제할 책임이 있다(제42조)":"양수인이 양도인의 상호를 계속 쓰면 양도인의 영업으로 생긴 제3자의 채권에 대해 양수인도 갚을 책임이 있습니다.","양수 후 지체 없이 책임이 없음을 등기하거나 양도인과 양수인이 제3자에게 그 뜻을 통지하면 책임을 지지 않는다":"양수 후 지체 없이 책임 없음을 등기하거나 제3자에게 통지하면 양수인은 책임을 지지 않습니다.","어떤 사유로든 어음 점유를 잃은 자가 있어도 배서의 연속으로 권리를 증명하는 소지인은 악의 또는 중대한 과실로 취득한 경우가 아니면 어음을 반환할 의무가 없다":"어음을 잃은 사람이 있어도 배서 연속으로 권리를 증명하는 소지인은 악의·중대한 과실이 없으면 반환의무가 없습니다.","어음 문구가 변조되면 변조 후에 기명날인하거나 서명한 자는 변조된 문구대로 책임을 지고 변조 전에 기명날인하거나 서명한 자는 원래 문구대로 책임을 진다":"어음 문구가 변조되면 변조 후 기명날인자는 변조된 문구대로, 변조 전 기명날인자는 원래 문구대로 책임집니다.","어음상 권리가 절차 흠결이나 시효로 소멸하고 원인채권 등 다른 구제수단도 없을 때 소지인은 발행인·인수인·배서인에게 그들이 받은 이익의 한도에서 상환을 청구한다":"어음상 권리가 소멸하고 다른 구제수단도 없으면 소지인은 발행인·인수인·배서인이 얻은 이익 한도에서 상환을 청구할 수 있습니다.","어음 앞면에 지급인의 단순한 기명날인만 있어도 인수로 보고(제25조) 일부인수는 할 수 있으며 다른 기재사항을 변경한 인수는 인수거절로 보되 인수인은 그 문구대로 책임을 진다(제26조)":"지급인의 단순한 기명날인만 있어도 인수로 보고, 일부인수가 가능하며 기재사항을 바꾼 인수는 거절이지만 그 문구대로 책임집니다.","어음요건 흠결, 시효 소멸, 위조, 제한능력 같은 물적 항변은 소지인의 선의·악의와 관계없이 누구에게나 주장할 수 있다":"물적 항변은 요건 흠결·시효·위조·제한능력 같은 사유로 소지인이 선의여도 누구에게나 주장됩니다.","어음은 설권증권·무인증권·요식증권이고 지시식으로 발행하지 않아도 배서로 양도하는 당연한 지시증권이다":"어음은 증권으로 권리를 만들고, 원인과 분리되며, 요건이 정해진 증권으로 지시식 문구 없이도 배서로 양도됩니다.","어음채무자는 발행인이나 종전 소지인에 대한 인적 관계로 인한 항변으로 소지인에게 대항하지 못하지만 소지인이 채무자를 해할 것을 알고 취득했으면 대항할 수 있다(제17조)":"어음채무자는 발행인이나 종전 소지인에 대한 인적 항변을 소지인에게 주장하지 못하지만, 소지인이 채무자를 해할 것을 알고 취득하면 가능합니다.","언제든지 이사에게 영업 보고를 요구하고 업무·재산상태를 조사하고, 모회사 감사는 필요하면 자회사에 영업 보고를 요구한다":"감사는 이사에게 영업 보고를 요구하고 업무·재산을 조사할 수 있으며, 모회사 감사는 자회사에 영업 보고를 요구할 수 있습니다.","업무가 현저한 정돈상태로 회복할 수 없는 손해가 생기거나 회사재산 관리·처분의 현저한 실당으로 존립이 위태로울 때 부득이한 사유가 있으면 발행주식총수의 10% 이상 주주가 법원에 해산을 청구할 수 있다":"회사 업무나 재산 관리의 현저한 실당으로 존립이 위태로울 때 부득이한 사유가 있으면 10% 이상 주주가 법원에 해산을 청구할 수 있습니다.","업무집행과 대표를 하지 못하지만 경업·겸직 제한은 받지 않는다":"유한책임사원은 업무집행과 대표를 못 하는 대신 경업·겸직 제한은 받지 않습니다.","업무집행자의 자기거래는 다른 사원 과반수의 결의가 있어야 한다":"업무집행자가 회사와 거래하려면 다른 사원 과반수의 결의를 받아야 합니다.","여럿이 그 1인 또는 전원에게 상행위가 되는 행위로 채무를 지면 연대하여 변제할 책임이 있다(제57조 제1항)":"여럿이 한 사람 이상에게 상행위가 되는 행위로 채무를 지면 연대하여 책임집니다.","연 1회의 결산기를 정한 회사만 정관으로 정하여 영업연도 중 1회에 한해 이사회 결의로 일정한 날의 주주에게 중간배당을 할 수 있다":"중간배당은 연 1회 결산기를 정한 회사만 정관으로 정해 영업연도 중 1회에 한해 이사회 결의로 할 수 있습니다.","영업범위 안에서 임치를 받은 상인은 보수가 없어도 선량한 관리자의 주의를 한다":"상인이 영업 범위 안에서 물건을 맡으면 무보수여도 선량한 관리자의 주의 의무를 집니다.","영업범위 안에서 타인을 위하여 한 행위에는 상당한 보수를 청구할 수 있다":"영업의 범위 안에서 남을 위한 행위를 한 상인은 상당한 보수를 달라고 할 수 있습니다.","영업으로 하는 매매, 임대차, 제조·가공, 운송·임치의 인수, 금융리스 등 제46조 각 호의 행위가 기본적 상행위이고, 오로지 임금을 받을 목적으로 제조하거나 노무에 종사하는 행위는 제외한다":"영업으로 하는 매매·임대차·제조·운송·금융리스 등이 기본적 상행위이며, 임금을 받으려는 제조·노무 종사는 제외합니다.","영업의 전부 또는 중요한 일부의 양도":"영업 전부나 중요한 일부를 양도하는 것은 주주총회 특별결의를 거쳐야 하는 사항입니다.","영업의 특정한 종류나 사항을 위임받은 사용인은 그에 관한 재판외의 모든 행위를 할 수 있다(제15조)":"특정한 종류나 사항의 영업을 위임받은 사용인은 그 범위 안에서 재판외 모든 행위를 할 수 있습니다.","영업 일부의 임대는 대상이 아니다":"영업의 일부를 빌려주는 임대는 특별결의 대상이 아닙니다.","완전모회사의 자본금은 완전자회사의 순자산액에서 주주에게 줄 금전 등을 뺀 금액을 넘지 못하고, 주식이전으로 모회사 주식을 취득한 자회사는 6월 내에 처분한다":"완전모회사의 자본금은 완전자회사 순자산에서 주주에게 줄 금전 등을 뺀 금액이 상한이고, 취득한 모회사 주식은 6월 내에 처분합니다.","완전자회사 총주주 동의나 완전모회사의 90% 이상 보유 시 간이교환, 완전모회사가 발행하는 신주가 10% 이하이고 교환대가가 순자산의 5% 이하이면 소규모교환이 되며 소규모교환은 계약서 작성일부터 2주 내에 공고·통지하고 20% 이상 반대 시 할 수 없다":"90% 이상 보유면 간이교환, 신주 10% 이하·대가 5% 이하면 소규모교환이며 소규모교환은 2주 내 공고하고 20% 이상 반대하면 못 합니다.","운송주선인·운송인·창고업자의 책임은 1년이 지나면 시효로 소멸":"운송주선인·운송인·창고업자의 책임은 1년의 단기시효에 걸립니다.","원인관계가 취소·해제되면 직접 상대방에게는 이를 인적 항변으로 주장해 어음금 지급을 거절할 수 있다":"원인관계가 사라지면 직접 거래 상대방에게는 그 사유를 인적 항변으로 내세워 지급을 거절할 수 있습니다.","위원 선임·해임 때 발행주식총수의 3%를 넘는 주식은 의결권이 제한되며 최대주주는 특수관계인 등을 합산한다":"위원 선임·해임 때는 3%를 넘는 주식 의결권을 제한하며 최대주주는 특수관계인 주식을 합산해 계산합니다.","위조된 기명날인이 있어도 다른 기명날인을 한 자의 채무는 영향을 받지 않으므로 위조어음에 배서한 자는 선의·무중과실이라도 배서인으로서 책임을 진다":"위조가 있어도 다른 기명날인자의 책임은 독립이라서, 위조어음에 배서한 자는 선의·무중과실이어도 책임을 집니다.","위조 주권·무효 처리된 주권은 선의취득의 대상이 아니다":"위조 주권이나 무효 처리된 주권은 선의취득 보호 대상이 되지 않습니다.","위탁매매로 취득한 물건·채권은 위탁자와 위탁매매인의 채권자 사이에서 위탁자의 소유나 채권으로 본다":"위탁매매에서 취득한 물건·채권은 위탁자의 채권자와의 관계에서는 위탁자의 재산입니다.","유한책임사원은 신용·노무를 출자하지 못하고 출자가액에서 이행한 부분을 뺀 금액을 한도로 회사채무를 변제한다":"합자회사의 유한책임사원은 신용·노무 출자가 안 되고, 출자가액 중 아직 이행하지 않은 부분만큼 책임을 집니다.","유한책임사원이 무한책임사원이 되면 변경 전 채무에도 무한책임을 진다":"유한책임사원이 무한책임사원으로 지위를 바꾸면 그 이전에 생긴 회사 채무까지 무한책임이 따라붙습니다.","은행이 발행인이고 분실자가 은행에 지급정지를 청구하는 것은 지급위탁의 취소가 아니다":"자기앞수표는 은행이 발행인이므로 분실자의 지급정지 청구는 지급위탁의 취소가 아닙니다.","음성을 동시에 송수신하는 원격통신 참가가 허용되며 대리 출석과 특별이해관계 이사의 의결권 행사는 허용되지 않는다":"이사회에는 음성을 동시에 주고받는 원격통신으로 참가할 수 있고 대리 출석과 특별이해관계 이사의 의결권 행사는 허용되지 않습니다.","의결권 없는 주식을 뺀 3% 이상 주주는 총회일 6주 전에 이사에게 서면·전자문서로 주주제안을 한다":"3% 이상 주주는 총회일 6주 전까지 서면이나 전자문서로 주주제안을 할 수 있습니다.","이 경우 이익배당도 이사회 결의로 정한다":"이사회가 재무제표를 승인하는 이 경우에는 이익배당도 이사회 결의로 정합니다.","이 규정은 창고증권에 준용한다":"화물상환증 규정은 창고증권에도 준용됩니다.","이사·감사 해임, 주식매수선택권 부여, 주식분할":"이사·감사 해임, 주식매수선택권 부여, 주식분할도 특별결의가 필요합니다.","이사 과반수 출석과 출석이사 과반수로 하고 정관으로 높일 수만 있다":"이사회 결의는 이사 과반수 출석과 출석이사 과반수로 하며 정관으로는 요건을 높일 수만 있습니다.","이사는 1인 이상이고 여럿이면 정관에 다른 정함이 없을 때 업무집행은 이사 과반수 결의로 하며 대표이사는 사원총회가 정한다":"이사는 1인 이상이고 여럿이면 업무집행은 이사 과반수로, 대표이사는 사원총회가 정합니다.","이사는 3명 이상이지만 자본금 10억원 미만 회사는 1명 또는 2명으로 할 수 있다":"이사 수는 3명 이상이 원칙이며 자본금 10억원 미만 소규모 회사만 1명 또는 2명도 가능합니다.","이사는 매 결산기 재무제표와 영업보고서를 작성해 이사회 승인을 받고, 감사는 서류를 받은 날부터 4주 내에 감사보고서를 이사에게 제출한다":"결산기마다 재무제표를 이사회가 승인하고, 감사는 서류를 받은 후 4주 안에 감사보고서를 내야 합니다.","이사는 언제든지 주주총회 특별결의로 해임할 수 있고, 임기를 정한 이사를 정당한 이유 없이 만료 전에 해임하면 손해배상을 청구할 수 있다(임기를 정하지 않았거나 이사회가 대표이사직만 해임한 경우는 아니다)":"이사는 언제든 특별결의로 해임할 수 있고, 임기를 정한 이사를 정당한 이유 없이 해임하면 손해배상을 청구할 수 있습니다.","이사는 인수인에게 납입기일에 인수가액 전액을 납입시키고, 인수인은 회사의 동의 없이 납입채무와 회사에 대한 채권을 상계하지 못한다":"인수인은 납입기일에 전액을 납입해야 하고 회사 동의 없이 자신의 채권과 납입채무를 상계하지 못합니다.","이사는 정기총회 1주간 전부터 서류를 본점에 5년, 등본을 지점에 3년 비치하고, 주주와 회사채권자는 영업시간 내에 언제든지 열람할 수 있다":"정기총회 1주 전부터 본점에 5년, 지점에 3년 비치해야 하고 영업시간 중 주주·채권자가 열람합니다.","이사는 주주총회에서 선임하고 선임결의와 본인의 승낙으로 지위를 얻고, 회사와 이사의 관계에는 위임 규정을 준용한다":"이사의 지위는 주주총회 선임결의와 이사 본인의 승낙으로 생기며, 회사와는 위임 관계로 봅니다.","이사·발기인의 회사에 대한 책임 면제와 주식회사의 유한책임회사 조직변경은 총주주의 동의가 있어야 한다":"이사·발기인의 책임 면제와 유한책임회사로의 조직변경은 총주주 동의가 필요합니다.","이사에 대한 유지청구와 임시총회 소집청구도 할 수 있다":"감사에게 유지청구권과 임시총회 소집청구권도 있습니다.","이사와 통모하여 현저하게 불공정한 가액으로 인수한 자는 회사에 공정가액과의 차액을 지급할 의무가 있다":"이사와 짜고 현저히 불공정한 가액으로 인수한 사람은 공정가액과의 차액을 회사에 내야 합니다.","이사의 위법행위 유지청구, 대표소송·다중대표소송(모회사 주식 기준), 총회 검사인 선임 청구":"이사의 위법행위 유지청구, 대표소송·다중대표소송, 총회 검사인 선임 청구는 소수주주 가운데 낮은 비율로도 가능한 권리입니다.","이사회 결의가 필요한 거래를 결의 없이 하면 상대방이 이를 알았거나 중대한 과실로 몰랐을 때만 무효이다(2021 전원합의체)":"이사회 결의가 필요한 거래를 결의 없이 했더라도 상대방이 알았거나 중과실로 몰랐을 때만 무효라는 2021년 전원합의체 판단입니다.","이사회 결의면 이사회가 정한 신주배정기준일에, 주주총회 결의면 결의한 때 주주가 된다":"전입으로 받는 신주의 주주 지위는 이사회 결의면 신주배정기준일에, 총회 결의면 결의한 때 생깁니다.","이사회는 각 이사가 소집하되 이사회 결의로 소집권자를 정할 수 있고, 소집권자가 정당한 이유 없이 거절하면 다른 이사가 직접 소집한다":"이사회는 원칙적으로 각 이사가 소집하고, 소집권자를 정했는데 그가 거절하면 다른 이사가 소집합니다.","이사회는 감사위원회의 결의를 다시 결의하지 못한다":"이사회는 감사위원회가 한 결의를 다시 결의하는 방식으로 뒤집을 수 없습니다.","이사회는 법령·정관 위반 등 제외사유가 없으면 이를 목적사항으로 하며 청구가 있으면 설명 기회를 준다":"제외사유가 없으면 이사회가 주주제안을 총회 목적사항으로 올리고, 제안자에게 설명할 기회도 줍니다.","이사회 승인(일반 결의)이 필요하고 위반 거래가 자기 계산이면 회사의 계산으로 볼 수 있다":"이사의 경업·겸직은 이사회의 일반 결의 승인이 필요하고, 위반 거래가 자기 계산이면 회사 계산으로 볼 수 있습니다.","이사회에 출석해 의견을 진술하되 의결권은 없고, 이사회 소집을 청구했는데 응하지 않으면 법원 허가 없이 직접 소집한다":"감사는 이사회에서 의견을 말할 수 있으나 의결권은 없고, 소집 청구에 이사가 응하지 않으면 법원 허가 없이 직접 소집합니다.","이사회의사록 열람·등사는 주주 단독으로 청구하고 회사가 거절하면 법원 허가를 얻어 열람한다":"주주는 혼자서 이사회 의사록 열람을 청구할 수 있고, 회사가 거절하면 법원의 허가를 받아 열람합니다.","이익배당, 잔여재산분배, 의결권 배제·제한, 상환, 전환에 관하여 내용이 다른 종류주식을 정관에 정하여 발행한다":"이익배당, 잔여재산분배, 의결권, 상환, 전환의 내용이 다른 종류주식은 정관에 정해 발행합니다.","이익배당은 대차대조표의 순자산액에서 자본금, 적립된 자본·이익준비금, 그 결산기에 적립할 이익준비금, 미실현이익을 뺀 금액을 한도로 하며 임의준비금은 빼지 않는다":"이익배당 한도는 순자산액에서 자본금, 법정준비금, 이번 결산기 적립 이익준비금, 미실현이익을 뺀 금액이고 임의준비금은 빼지 않습니다.","이자 약정은 일람출급과 일람 후 정기출급 어음에만 적을 수 있고 그 밖의 어음에 적은 이자 약정은 적지 않은 것으로 보며 이율이 없으면 이자 약정이 없는 것으로 보고 날짜가 없으면 발행한 날부터 이자를 계산한다":"이자 약정은 일람출급과 일람 후 정기출급 어음에서만 인정되고 이율이 없으면 약정이 없는 것으로 보며 날짜가 없으면 발행일부터 계산합니다.","이전은 사채원부 기재와 채권에 성명 기재가 있어야 회사·제3자에 대항하고 상환청구권 시효는 10년이다":"기명사채의 이전은 사채원부와 채권에 성명을 적어야 대항하며 상환청구권의 시효는 10년입니다.","이행시기가 지난 뒤 상대방이 즉시 이행을 청구하지 않으면 해제한 것으로 본다":"확정기매매에서 시기를 넘겼는데 상대방이 즉시 이행을 청구하지 않으면 해제된 것으로 봅니다.","익명조합원은 제3자에게 권리·의무가 없다":"익명조합원은 영업자의 거래 상대인 제3자에 대해 권리도 의무도 없습니다.","익명조합원이 출자한 재산은 영업자의 재산으로 본다":"출자한 재산의 소유는 영업자에게 속하는 것으로 봅니다.","인가일부터 1월 내에 발행하되 법원은 이 기간을 연장할 수 있으며 채권자 이의절차는 없다":"액면미달 발행은 인가일부터 1월 안에 하며, 법원이 기간을 연장할 수 있고 채권자 이의절차는 없습니다.","일람 후 정기출급 어음은 발행일부터 1년 내에 인수제시하며 발행인은 이 기간을 단축·연장하고 배서인은 단축만 할 수 있다(제23조)":"일람 후 정기출급 어음은 1년 안에 인수제시하되, 발행인은 기간을 늘리거나 줄일 수 있고 배서인은 줄이는 것만 가능합니다.","일반횡선은 특정횡선으로 바꿀 수 있지만 특정횡선은 일반횡선으로 바꾸지 못하며 횡선이나 지정 은행 명칭을 말소해도 하지 않은 것으로 본다":"일반횡선은 특정횡선으로 바꿀 수 있지만 반대는 안 되고, 횡선이나 은행 명칭을 지워도 효력이 없습니다.","임기는 3년을 넘지 못하되 정관으로 임기 중 최종 결산기에 관한 정기총회 종결 때까지 늘릴 수 있다":"이사의 임기는 3년 이내이나 정관으로 마지막 결산기 정기총회 종결 때까지 늘릴 수 있습니다.","임기 만료·사임으로 퇴임한 이사는 새 이사가 취임할 때까지 권리의무가 있다":"퇴임 이사는 후임이 취임할 때까지 이사로서 권리의무를 계속 갖습니다.","임시총회 소집청구, 주주제안, 집중투표 청구, 이사·감사·청산인 해임청구, 회계장부 열람, 업무·재산 검사인 선임 청구":"임시총회 소집, 주주제안, 집중투표, 이사·감사·청산인 해임, 회계장부 열람, 검사인 선임 청구가 이 지분율 요건 권리입니다.","임의해산, 회사 계속, 휴면회사 계속":"임의해산, 회사 계속, 휴면회사 계속도 특별결의 사항입니다.","임치기간 약정이 없으면 받은 날부터 6월이 지난 뒤 2주간 전에 예고하고 반환할 수 있다":"창고업자는 임치기간을 정하지 않았다면 6월이 지난 뒤 2주 전 예고로 반환할 수 있습니다.","입질배서의 피배서인도 질권을 선의취득할 수 있다":"입질배서를 받은 사람도 질권을 선의로 취득할 수 있습니다.","자기를 무한책임사원으로 오인시킨 유한책임사원은 오인하고 거래한 자에게 무한책임사원과 같은 책임을 진다":"유한책임사원이 무한책임사원으로 오인하게 만들었다면 그 오인으로 거래한 사람에게 무한책임을 집니다.","자기명의로 상행위를 하는 자":"당연상인은 상행위를 하는 사람이 자기 이름으로 그 행위를 할 때 성립합니다.","자기명의로 타인의 계산으로 물건이나 유가증권의 매매를 영업으로 하며 상대방에게 직접 권리를 취득하고 의무를 진다":"위탁매매인은 자기 이름으로 남의 계산을 위해 물건이나 유가증권을 사고파는 사람이며 상대방에게 직접 권리·의무를 가집니다.","자기 성명이나 상호로 영업할 것을 허락한 자는 자기를 영업주로 오인하여 거래한 제3자에게 그 타인과 연대하여 변제할 책임을 진다(제24조)":"자기 성명이나 상호로 영업하도록 허락한 사람은 영업주로 오인해 거래한 제3자에게 그 타인과 연대해 책임집니다.","자기주식, 의결권 없는 종류주식, 10분의 1 초과 상호보유로 의결권이 없는 주식은 발행주식총수에 넣지 않는다":"상호보유로 의결권이 제한되는 주식, 자기주식, 의결권 없는 종류주식은 발행주식총수 계산에서 제외합니다.","자기지시수표, 제3자의 계산으로 하는 위탁수표, 발행인 자신을 지급인으로 하는 자기앞수표를 모두 발행할 수 있다":"수표는 자기지시수표, 위탁수표, 자기앞수표 세 형태로 발행할 수 있습니다.","자본금 감소는 주주총회 특별결의로 하고 감소 방법을 정한다":"자본금을 줄이려면 주주총회 특별결의로 감소 방법을 정해야 합니다.","자본금은 발행주식의 액면총액이다":"액면주식 회사의 자본금은 발행주식의 액면총액입니다.","자본준비금과 이익준비금은 어느 것이든 결손 보전에 충당할 수 있다":"이익준비금과 자본준비금은 모두 결손 보전에 충당할 수 있습니다.","자산총액 2조원 이상 상장회사는 1% 이상 주주가 총회일 6주 전까지 청구할 수 있고 2025.9.9 개정으로 정관으로 집중투표를 배제할 수 없다":"상장회사 중 자산총액 2조원 이상은 1% 이상 주주가 총회 6주 전까지 청구하며 2025.9.9 개정으로 정관으로 배제할 수 없습니다.","자산총액 2조원 이상 상장회사는 감사위원회를 두어야 하고 위원의 선임·해임은 주주총회 권한이며 정관으로도 이사회에 넘기지 못한다":"2조원 이상 상장회사는 감사위원회 설치가 의무이고, 위원 선임·해임 권한을 이사회에 위임할 수 없습니다.","자산총액 5천억원 이상 상장회사는 준법통제기준과 준법지원인(임기 3년)을 둔다":"자산총액 5천억원 이상 상장회사는 준법통제기준을 마련하고 임기 3년의 준법지원인을 둡니다.","자회사는 합병·주식교환·이전, 영업 전부 양수, 권리 실행의 경우에만 모회사 주식을 취득해 6월 내에 처분한다":"자회사는 합병·주식교환 등 예외 경우에만 모회사 주식을 취득하고 6월 내 처분해야 합니다.","재무제표를 승인하고 영업보고서는 보고만 받는다":"정기총회에서는 재무제표를 승인하고, 영업보고서는 보고만 받습니다.","재무제표 승인과 총회의 검사인 선임은 보통결의이고 중간배당은 이사회가 정한다":"재무제표 승인은 보통결의, 검사인 선임도 보통결의이며, 중간배당은 이사회가 정합니다.","재무제표 승인 후 2년 내에 다른 결의가 없으면 이사·감사의 책임을 해제한 것으로 보되 부정행위는 해제되지 않는다":"재무제표를 승인한 뒤 2년 동안 다른 결의가 없으면 책임이 풀리지만 부정행위 책임은 남습니다.","재무제표 승인 후 2년 내에 다른 결의가 없으면 책임을 해제한 것으로 보지만 부정행위로 인한 책임은 해제되지 않는다":"재무제표 승인 뒤 2년이 지나도록 다른 결의가 없으면 책임이 해제되나, 부정행위는 해제 대상에서 제외됩니다.","재무제표·영업보고서·감사보고서와 정관·총회의사록·주주명부는 주주와 채권자가 영업시간 내에 열람할 수 있다":"재무제표와 정관, 총회의사록, 주주명부 같은 서류는 영업시간 내 주주와 채권자에게 열람이 허용됩니다.","전부멸실·연착이면 인도할 날, 일부멸실·훼손이면 인도한 날의 도착지 가격으로 정한다":"배상액 기준 시점은 전부멸실·연착은 인도할 날, 일부멸실·훼손은 인도한 날이며 가격은 도착지 가격입니다.","전자투표를 도입한 회사는 출석 의결권의 과반수만으로 감사를 선임할 수 있고, 자본금 10억원 미만 회사는 감사를 두지 않을 수 있다":"전자투표를 도입하면 출석 의결권 과반수로 감사를 뽑을 수 있고, 소규모 회사는 감사를 생략해도 됩니다.","전환권은 사채와 분리하여 양도할 수 없고, 신주인수권증권이 발행되면 신주인수권은 증권의 교부로만 양도하며 선의취득이 인정된다":"전환권은 사채와 따로 양도할 수 없고, 신주인수권증권은 교부로만 양도하며 선의취득이 됩니다.","전환으로 발행하는 신주식의 발행가액은 전환 전 주식의 발행가액이고 새로 발행할 주식 수는 전환기간 동안 발행을 유보한다":"전환 신주식의 발행가액은 전환 전 주식과 같고, 전환기간 동안 새로 발행할 주식 수를 유보해 둡니다.","점포 등 설비에 의하여 상인적 방법으로 영업하는 자와 회사는 상행위를 하지 않더라도 상인으로 본다":"점포 같은 설비를 갖춰 상인적 방법으로 영업하는 사람과 회사는 상행위를 안 해도 상인으로 취급하는 의제상인입니다.","정관변경, 영업양도 등(제374조), 사후설립":"정관변경, 영업양도 등(제374조), 사후설립은 주주총회 특별결의 사항입니다.","정관변경과 지분 전부·일부 양도는 총사원(다른 사원 전원)의 동의가 필요하다":"정관을 바꾸거나 지분을 양도하려면 다른 사원 전원의 동의가 필요합니다.","정관변경은 총사원 반수 이상이며 의결권 4분의 3 이상으로 하고, 소수사원권(대표소송 등)은 자본금 3% 이상 출자좌수가 기준이며 집중투표 제도는 없다":"유한회사의 정관변경은 총사원 반수 이상이며 의결권 4분의 3 이상이 필요하고, 소수사원권은 자본금 3% 이상 기준이며 집중투표는 없습니다.","정관에 근거가 있으면 금전 외의 재산으로 배당할 수 있고, 일반 이익배당처럼 주주총회 보통결의(재무제표를 이사회가 승인하는 회사는 이사회 결의)로 정한다":"정관에 근거가 있으면 금전 외 재산으로도 배당하며, 결정은 일반 이익배당과 마찬가지로 보통결의나 이사회 결의로 합니다.","정관에 근거를 두고 주주총회 특별결의로 부여하고, 10% 이상 주주, 경영에 사실상 영향력을 행사하는 자와 그 배우자·직계존비속에게는 줄 수 없고 행사로 발행·양도할 주식은 발행주식총수의 10%를 넘지 못한다":"매수선택권은 특별결의로 부여하며 10% 이상 주주와 영향력 있는 자 등은 제외되고 행사 한도는 발행주식총수의 10%입니다.","정관에 다른 정함이 없으면 총사원의 동의가 필요하고, 자본금은 정관변경으로 감소하되 감소 후 자본금이 순자산액 이상이면 채권자 이의절차가 필요 없다":"정관변경은 총사원 동의가 필요하고, 자본금 감소 후 자본금이 순자산액 이상이면 채권자 이의절차가 필요 없습니다.","정관에 따라 감사에 갈음하여 설치하고 설치하면 감사를 둘 수 없다":"감사위원회는 정관에 근거해 감사 대신 설치하며 설치하면 감사를 따로 둘 수 없습니다.","정관에 따라 증서 대신 전자등록부에 신주인수권을 등록할 수 있다":"신주인수권증서 대신 전자등록부에 권리를 등록하는 것도 정관으로 가능합니다.","정관에 따른 보수 6배 초과 면제는 고의·중과실이면 적용되지 않는다":"보수 6배 초과 책임 면제 특례는 감사에게 고의나 중과실이 있으면 쓸 수 없습니다.","정관에 정함이 없으면 각 사원이 업무를 집행하고 대표하며, 업무집행사원은 정관으로 정하고 다른 업무집행사원의 이의가 있으면 행위를 중지하고 과반수 결의에 따른다":"정관에 달리 정하지 않으면 사원 각자가 업무를 집행·대표하고, 업무집행사원이 정해지면 다른 업무집행사원의 이의 시 중지하고 과반수로 결정합니다.","정관으로 사원 또는 사원이 아닌 자를 업무집행자로 정하고 법인도 업무집행자가 될 수 있으며, 둘 이상이면 각자 업무를 집행하고 정관이나 총사원의 동의로 대표 업무집행자를 정할 수 있다":"업무집행자는 정관으로 사원이나 비사원, 법인도 정할 수 있고, 둘 이상이면 각자 집행하며 대표 업무집행자를 정할 수 있습니다.","정관으로 정하면 외부감사인의 적정의견과 감사(감사위원) 전원의 동의를 요건으로 이사회 결의로 재무제표를 승인할 수 있고, 이때 이사는 그 내용을 주주총회에 보고한다":"정관에 정하면 외부감사인의 적정의견과 감사 전원 동의로 이사회가 재무제표를 승인할 수 있고, 이사는 그 내용을 총회에 보고합니다.","정관으로 정하면 주식의 전부를 무액면주식으로 발행할 수 있다(액면주식과 혼용 불가)":"정관으로 정하면 주식 전부를 무액면주식으로 발행할 수 있고 액면주식과 섞어 쓸 수 없습니다.","정관으로 정한 자격주는 감사에게 공탁하고, 보수는 정관에 없으면 주주총회가 정한다":"보수는 정관에 정함이 없으면 주주총회가 정하고, 정관상 자격주는 감사에게 공탁합니다.","정관으로 제한하지 않으면 자유롭게 양도하고 사원명부 기재가 회사·제3자 대항요건이며, 지시식·무기명식 증권을 발행하지 못하고 질권 설정은 되지만 약식질은 없다":"유한회사 지분은 자유롭게 양도되고 사원명부 기재가 대항요건이며, 지시식·무기명식 증권을 못 만들고 약식질은 없습니다.","정관으로 주식 양도에 이사회 승인을 받게 할 수 있고, 승인 없는 양도는 회사에 효력이 없지만 당사자 사이에서는 유효 → 회사는 승인 청구일부터 1월 내에 서면으로 통지 → 거부 통지를 받은 주주는 20일 내에 상대방 지정이나 주식매수를 청구 → 이사회가 지정 청구일부터 2주간 내에 지정 통지를 하지 않거나 지정된 자가 10일 내에 매도청구를 하지 않으면 양도를 승인한 것으로 보며, 양수인도 취득 승인을 청구할 수 있다":"이사회 승인 없는 양도는 회사에 효력이 없으나 당사자 사이에선 유효하며, 거부 통지를 받은 주주는 20일 안에 지정·매수를 청구할 수 있습니다.","정관은 공증인의 인증으로 효력이 생기지만 자본금 10억원 미만 회사를 발기설립하면 발기인의 기명날인·서명만으로 효력이 생긴다":"정관은 공증인의 인증을 받아야 효력이 생기지만, 자본금 10억원 미만 발기설립은 발기인 서명만 있으면 됩니다.","정관이나 이사회 결의로 신주인수권을 양도할 수 있음을 정한 경우 양도는 신주인수권증서의 교부로만 하고 점유자는 적법한 소지인으로 추정된다":"신주인수권 양도를 정관이나 이사회 결의로 정한 경우 양도는 증서 교부로만 하며 점유자는 적법한 소지인으로 추정됩니다.","정당한 이유 없이 임기 중 해임되면 손해배상을 청구하며 총회에서 해임에 관한 의견을 진술할 수 있다":"임기 중 정당한 이유 없이 해임된 감사는 손해배상을 청구할 수 있고 총회에서 해임에 관한 의견을 진술할 수 있습니다.","제시기간 내에 제시했으나 지급받지 못한 소지인이 거절증서, 날짜를 부기한 지급인의 선언, 어음교환소의 선언 중 하나로 거절을 증명하면 배서인·발행인 등에게 상환청구할 수 있다":"제시기간 안에 제시했으나 지급받지 못한 소지인은 거절증서, 지급인의 선언, 어음교환소 선언 중 하나로 거절을 증명해 상환청구합니다.","조직변경은 합명↔합자, 주식↔유한회사, 주식↔유한책임회사 사이에서만 인정된다":"조직변경이 허용되는 짝은 합명↔합자, 주식↔유한회사, 주식↔유한책임회사뿐입니다.","존립기간 만료 등 정관 사유, 총사원의 동의, 사원이 1인으로 된 때, 합병, 파산, 법원의 명령·판결로 해산하고, 사원 1인이 되면 새 사원을 가입시켜 계속할 수 있다":"합명회사는 정관 사유, 총사원 동의, 사원 1인, 합병, 파산, 법원 명령·판결로 해산하며 사원 1인이면 새 사원 가입으로 계속할 수 있습니다.","존립기간 만료 등 정관 사유나 총회 결의로 해산한 회사는 특별결의로 계속할 수 있다":"정관 사유나 총회 결의로 해산했다면 특별결의로 회사를 계속할 수 있습니다.","존립기간 만료 등 정관에 정한 사유, 합병, 분할·분할합병, 파산, 법원의 해산명령·해산판결, 주주총회 특별결의":"해산사유는 정관 사유(존립기간 만료 등), 합병, 분할, 파산, 법원의 해산명령·판결, 주주총회 특별결의입니다.","존립 중의 회사를 존속회사로 하거나 새로 회사를 설립하는 경우에만 분할할 수 있다":"분할이 가능한 것은 존립 중 회사가 존속하거나 새 회사를 설립하는 경우입니다.","존속기간 약정이 없으면 2월 전에 예고하고 해지할 수 있다":"대리상 계약은 존속기간 약정이 없으면 2월 전 예고로 해지할 수 있습니다.","존속회사가 발행하는 신주가 발행주식총수의 10% 이하이고 금전 등 대가가 존속회사 순자산의 5% 이하인 때 존속회사 총회 승인을 이사회 승인으로 갈음":"소규모합병은 존속회사의 신주가 발행주식총수의 10% 이하이고 대가가 순자산의 5% 이하일 때 존속회사 총회 승인을 이사회로 갈음합니다.","존속회사가 주식회사이고 상대가 합명·합자회사면 그 총사원의 동의로 합병계약서를 작성한다":"상대가 합명·합자회사이면 그 회사 총사원의 동의로 합병계약서를 만듭니다.","존속회사 주주는 매수청구를 할 수 없고 20% 이상 주주가 반대하면 할 수 없다":"소규모합병에서 존속회사 주주는 매수청구를 못 하고, 20% 이상 주주가 반대하면 소규모합병을 할 수 없습니다.","존속회사 주주만 매수청구를 못 한다":"소규모합병에서는 존속회사의 주주만 주식매수청구권이 없습니다.","종료 전 5년간의 평균연보수액을 넘지 못한다":"보상액은 계약 종료 전 5년 동안의 평균연보수액을 넘을 수 없습니다.","주권 발행 전 양도는 회사에 효력이 없으나 회사 성립 후 또는 신주 납입기일 후 6월이 지나면 의사표시만으로 회사에 효력이 있다":"주권 발행 전 양도는 회사에 대항하지 못하지만 성립 후나 납입기일 후 6월이 지나면 의사표시만으로 회사에 효력이 있습니다.","주권 발행 후의 양도는 주권을 교부해야 하고 주권 점유자는 적법한 소지인으로 추정된다":"주권 발행 후 주식 양도는 주권 교부가 필요하고, 주권을 점유한 사람은 적법한 소지인으로 추정됩니다.","주권은 회사 성립 후 또는 신주 납입기일 후 지체 없이 발행하고 그 전에 발행한 주권은 무효다":"성립 전이나 납입기일 전에 발행한 주권은 효력이 없고 지체 없이 발행해야 합니다.","주권을 잃은 자는 공시최고를 거쳐 제권판결을 받아야 재발행을 청구한다":"주권을 잃은 사람은 공시최고와 제권판결을 거쳐야 주권 재발행을 청구할 수 있습니다.","주권을 제시한 양수인은 단독으로 명의개서를 청구할 수 있다":"주권을 보여 주는 양수인은 혼자서 명의개서를 청구할 수 있습니다.","주소는 본점소재지이고 본점소재지에서 설립등기를 함으로써 성립하며 해산 후에도 청산 목적 범위에서 권리능력이 남는다":"회사의 주소는 본점소재지이고 그곳에서 설립등기를 해야 성립하며 해산 후에도 청산 목적 범위 안에서는 권리능력이 남습니다.","주식 공유자는 권리를 행사할 자 1인을 정하며 그가 없으면 회사의 통지는 공유자 1인에게 하면 된다":"주식을 공유하면 권리행사자 1인을 정하며, 없으면 회사는 공유자 1인에게만 통지해도 됩니다.","주식교환계약서를 주주총회 특별결의로 승인하고 채권자보호절차는 없고, 계약서에 정한 교환일에 완전자회사 주식이 완전모회사로 이전한다":"주식교환은 계약서를 특별결의로 승인하며 채권자보호절차가 없고, 교환일에 완전자회사 주식이 완전모회사로 넘어갑니다.","주식배당을 받은 주주는 결의한 총회가 종결한 때부터 신주의 주주가 되고 등록질권자의 권리는 새 주식에 미친다":"주식배당을 받으면 결의한 총회가 끝날 때부터 신주의 주주가 되고, 등록질권도 신주에 미칩니다.","주식의 권면액으로 하고 종류주식 회사는 같은 종류의 주식으로 할 수 있으며, 액면총액만큼 자본금이 늘어난다":"주식배당의 발행가는 액면총액이고 그만큼 자본금이 늘어나며, 종류주식 회사는 같은 종류 주식으로 줄 수 있습니다.","주식이전은 완전모회사가 본점소재지에서 설립등기를 함으로써 효력이 생기고, 간이·소규모 이전 제도는 없다":"주식이전은 완전모회사의 설립등기로 효력이 생기며 간이·소규모 이전은 없습니다.","주식인수로 인한 권리(권리주)의 양도는 회사에 효력이 없다":"주식인수로 생긴 권리인 권리주의 양도는 회사에 대해 효력이 없습니다.","주식청약서에 설립 찬조의 뜻을 적도록 승낙한 자도 발기인과 같은 책임을 진다":"설립 찬조 뜻을 주식청약서에 적도록 승낙하면 발기인과 같은 책임이 생깁니다.","주식 총수가 인수되면 발기인이 인수가액 전액을 납입 → 미납 인수인에게 기일의 2주간 전에 실권예고를 통지해 그 기일까지 납입하지 않아야 권리를 잃는다 → 변태설립사항은 발기인이 검사인 선임을 청구하고 창립총회가 변경하며, 납입금 보관자·장소 변경은 법원 허가를 받는다 → 창립총회 결의는 출석 인수인 의결권의 3분의 2 이상이며 인수된 주식 총수의 과반수로 하고, 소집통지에 없어도 정관변경·설립폐지를 결의할 수 있다":"모집설립은 전액 납입을 거쳐 실권예고를 하며, 창립총회는 출석 인수인의 3분의 2 이상과 인수 총수 과반수로 결의합니다.","주식회사→유한회사·유한책임회사는 총주주의 동의가 필요하고 사채 상환을 끝내지 않은 주식회사는 유한회사가 되지 못한다":"주식회사에서 유한(책임)회사로 바꾸려면 총주주의 동의가 필요하고, 사채 상환을 끝내지 않은 회사는 유한회사가 될 수 없습니다.","주식회사·유한회사·유한책임회사는 사원 1인으로 설립할 수 있고 합명·합자회사는 2인 이상이 필요하다":"사원이 한 명뿐이어도 주식회사·유한회사·유한책임회사는 설립할 수 있지만 합명·합자회사는 2인 이상입니다.","주의를 게을리하지 않았음을 증명하지 못하면 운송물의 멸실·훼손·연착 손해를 배상한다":"운송인과 주선인이 주의를 다했다는 증명을 못 하면 운송물의 멸실·훼손·연착 손해를 물어 줍니다.","주주가 1인이 되는 것은 해산사유가 아니다":"주주가 한 명이 되어도 주식회사는 해산하지 않습니다.","주주가 전환을 청구하면 청구한 때, 회사가 전환하면 주권제출기간이 끝난 때 효력이 생긴다":"전환주식은 주주의 청구가 있으면 청구한 때, 회사가 전환하면 주권제출기간이 끝난 때 효력이 발생합니다.","주주가 제소하면 회사의 청구로 담보 제공을 명할 수 있으나 그 주주가 이사·감사이면 명하지 못한다":"주주가 소를 내면 회사가 담보 제공을 구할 수 있으나 제소 주주가 이사·감사인 경우에는 구할 수 없습니다.","주주가 지분 요건 없이 청구한다":"이사회 의사록은 지분 요건 없이 주주 누구나 열람을 청구할 수 있습니다.","주주가 현물 대신 금전 지급을 청구할 수 있게 하면 그 금액과 청구기간을 정하고, 일정 수 미만 주식을 가진 주주에게 금전을 지급하도록 정할 수도 있다":"주주가 금전으로 받기를 원하면 그 금액과 청구기간을 정하고, 소수 주식 보유 주주에게 금전을 주도록 정할 수도 있습니다.","주주는 법률상 당연히 가진 주식 수에 따라 신주의 배정을 받을 권리가 있다(제418조 제1항)":"주주는 법률상 당연히 주식 수에 비례해 신주를 배정받을 권리가 있습니다.","주주는 정관에 다른 정함이 없으면 주권 발행 전후를 가리지 않고 불소지 신고를 할 수 있고, 이미 발행된 주권은 회사에 제출한다":"불소지 신고는 주권 발행 전후와 상관없이 할 수 있고, 이미 발행된 주권은 회사에 내야 합니다.","주주명부는 본점에 두고 명의개서대리인을 둔 때에는 그 영업소에도 둘 수 있다":"본점에 비치하고 명의개서대리인을 둔 경우 그 영업소에도 주주명부를 둘 수 있습니다.","주주명부 폐쇄기간 중에 전환된 주식은 그 기간 중의 총회에서 의결권을 행사하지 못한다":"명부 폐쇄기간에 전환된 주식은 폐쇄기간 총회에서 의결권이 없습니다.","주주에게 주식 수에 따라 신주를 발행한다":"준비금을 자본금에 전입하면 주주에게 주식 수에 비례해 신주를 발행합니다.","주주 외의 자에게 발행하면 정관에 규정이 없을 때 주주총회 특별결의로 정하고 경영상 목적이 필요하다":"주주 외의 자에게 전환사채·신주인수권부사채를 발행하려면 정관에 없을 때 특별결의와 경영상 목적이 필요합니다.","주주 외의 자에게 배정하려면 정관에 근거가 있고 신기술 도입·재무구조 개선 등 경영상 목적을 달성하는 데 필요해야 한다":"주주 외의 자에게 신주를 배정하려면 정관 근거가 있어야 하고 신기술 도입·재무구조 개선 같은 경영상 목적이 필요합니다.","주주의 책임은 주식의 인수가액을 한도로 한다":"주주의 책임은 인수가액을 한도로 하는 유한책임입니다.","주주·이사·감사가 결의일부터 2월 내에 제기한다(회사채권자는 제기 못 함)":"결의취소의 소는 주주·이사·감사가 결의일부터 2월 안에 제기하며 회사채권자는 제기할 수 없습니다.","주주·이사·감사가 신주 발행일부터 6월 내에 소로만 주장한다":"신주발행무효의 소는 주주·이사·감사가 발행일부터 6월 안에 소로만 제기할 수 있습니다.","주주·이사·감사·청산인·파산관재인과 감자를 승인하지 않은 채권자가 변경등기일부터 6개월 내에 회사를 피고로 소로만 주장한다":"감자무효의 소는 주주 등과 감자를 승인하지 않은 채권자가 변경등기일로부터 6개월 안에 회사를 상대로 제기합니다.","주주 전원의 동의가 있으면 소집절차 없이 총회를 열 수 있고 서면결의로 결의를 갈음할 수 있다":"전원 동의 시 소규모 회사는 소집 없이 총회를 열거나 서면결의로 대신합니다.","주주총회 결의로 이익배당을 새로 발행하는 주식으로 할 수 있으나 이익배당총액의 2분의 1을 넘지 못한다":"이익배당을 신주로 줄 수 있는 주식배당은 이익배당총액의 2분의 1을 넘지 못합니다.","주주총회 특별결의로 신설·승계회사가 분할계획서나 분할합병계약서에 승계하기로 정한 채무만 책임지도록 정할 수 있고, 이때 채권자보호절차를 거친다":"특별결의로 분할계획서에 승계하기로 정한 채무만 책임지도록 정할 수 있고, 이때 채권자보호절차를 거칩니다.","준비금의 자본금 전입은 이사회가 정하고 정관으로 주주총회 결의사항으로 할 수 있다":"준비금 전입은 이사회 권한이나 정관으로 총회 결의사항으로 바꿀 수 있습니다.","준비금 총액이 자본금의 1.5배를 넘으면 주주총회 결의로 초과액 범위에서 감액할 수 있다":"자본금의 1.5배를 넘는 준비금은 총회 결의로 초과액 한도에서 줄일 수 있습니다.","중간배당도 현물로 할 수 있다":"현물로도 중간배당을 할 수 있습니다.","중간배당은 주주총회가 아니라 이사회 결의사항이다":"중간배당의 결정 기관은 주주총회가 아니라 이사회입니다.","중개인은 다른 약정이나 관습이 없으면 중개한 행위에 관하여 당사자를 위한 지급을 받지 못한다":"중개인은 다른 약정이나 관습이 없으면 중개한 행위에 대해 당사자를 위해 지급을 받을 수 없습니다.","증권을 교부하면 운송물을 인도한 것과 같은 물권적 효력이 있다":"운송물 인도와 같은 물권적 효력이 증권 교부만으로 생깁니다.","증서를 발행하면 증서로 청약하되 증서를 잃은 자는 주식청약서로 청약할 수 있다":"신주인수권증서를 발행하면 증서로 청약하지만 증서를 잃은 사람은 주식청약서로 청약할 수 있습니다.","지급거절증서가 작성된 뒤나 작성기간이 지난 뒤에 한 배서는 지명채권 양도의 효력만 있고 만기 후라도 그 전에 한 배서는 만기 전 배서와 같다":"거절증서 작성 후 한 배서는 지명채권 양도 효력만 가지며, 만기 뒤라도 그 전에 한 배서는 만기 전 배서와 같습니다.","지급보증은 수표 앞면에 지급보증 등 지급하겠다는 뜻을 적고 날짜를 부기해 지급인이 기명날인하거나 서명하고 조건 없이 해야 하며 기재사항을 바꾼 부분은 바꾸지 않은 것으로 본다(제54조)":"지급보증은 앞면에 지급하겠다는 뜻과 날짜를 적고 지급인이 기명날인해야 하며 조건 없이 해야 하고, 기재사항을 바꾼 부분은 없는 것으로 봅니다.","지급보증을 한 지급인은 제시기간이 지나기 전에 제시된 경우에만 지급의무를 지고 발행인 등은 지급보증으로 책임을 면하지 못하며(제55조·제56조) 금액 일부의 지급보증은 할 수 없다":"지급보증인은 제시기간 안에 제시된 경우에만 지급의무를 지고, 일부 보증은 안 되며 발행인 등은 지급보증으로 책임을 면하지 못합니다.","지급위탁의 취소는 제시기간이 지난 후에만 효력이 생기고 취소가 없으면 지급인은 제시기간이 지난 뒤에도 지급할 수 있다":"위탁 취소는 제시기간이 지나야 효력이 있고, 취소가 없으면 제시기간 후에도 지급인이 지급할 수 있습니다.","지급위탁 취소는 수표행위가 아니어서 방식 제한이 없고 구두로도 할 수 있다":"위탁 취소는 수표행위가 아니라서 방식 제한 없이 말로도 할 수 있습니다.","지급인은 은행이나 자기 거래처에만 지급하고 이를 어긴 지급인이나 은행은 수표금액 한도에서 손해를 배상한다":"일반횡선수표는 은행이나 자기 거래처에만 지급해야 하고, 어기면 지급인이나 은행이 수표금액 한도에서 손해를 배상합니다.","지급인이 지급보증을 거절해도 상환청구 사유가 되지 않고 지급보증인에 대한 청구권은 제시기간이 지난 후 1년의 시효로 소멸한다(제58조)":"지급을 보증해 달라는 요청을 지급인이 거절해도 상환청구 사유가 안 되며, 지급보증인에 대한 청구권은 제시기간 후 1년이면 소멸합니다.","지급지가 없으면 지급인 명칭에 부기한 지(여러 개면 맨 앞에 적은 지), 그것도 없으면 발행지에서 지급하고 발행지가 없으면 발행인 명칭에 부기한 지를 발행지로 본다":"지급지가 없으면 지급인 명칭 옆 지에서 지급하고, 없으면 발행지에서 지급하며 발행지가 없으면 발행인 명칭 옆 지입니다.","지명채권 양도 방식으로만 양도한다":"지시금지 수표는 지명채권 양도 방식으로만 넘길 수 있습니다.","지명채권이라서 선의취득 대상이 아니고 약속어음 발행인이 반환할 이득은 원인관계로 받은 대가다":"이득상환청구권은 지명채권의 성질이어서 선의취득이 안 되고, 약속어음 발행인이 돌려줄 이득은 원인관계상 대가입니다.","지배인·상호·상업장부·상업등기 규정은 소상인에게 적용하지 않는다(제9조)":"소상인에게는 지배인·상호·상업장부·상업등기 규정이 적용되지 않습니다.","지배인 선임·해임, 지점 설치·이전·폐지 등 업무집행은 이사회가 정한다":"이사회가 지배인 선임·해임과 지점 설치·이전·폐지를 결정합니다.","지배인 선임·해임은 업무집행사원이 있어도 총사원 과반수로 한다":"합명회사에서는 업무집행사원이 있어도 총사원 과반수가 지배인을 뽑고 해임합니다.","지배인은 영업주에 갈음하여 영업에 관한 재판상·재판외의 모든 행위를 하고, 지배인 아닌 사용인을 선임·해임할 수 있다":"지배인은 영업주를 대신해 영업에 관한 모든 재판상·재판외 행위를 할 수 있고, 지배인이 아닌 사용인의 선임·해임도 가능합니다.","지분 양도는 다른 사원의 동의가 필요하며 회사는 자기 지분을 양수하지 못하고 취득하면 그때 소멸한다":"지분 양도에는 다른 사원의 동의가 필요하고, 회사는 자기 지분을 양수할 수 없으며 취득하면 그때 소멸합니다.","지분 양도는 무한책임사원 전원의 동의로 하며 사망하면 상속인이 승계하고 성년후견개시로 퇴사하지 않는다":"유한책임사원의 지분 양도는 무한책임사원 전원 동의가 필요하며 상속되고 성년후견개시로 퇴사하지 않습니다.","지시금지어음과 기한후배서 어음은 선의취득이 없고 선의취득으로 인적 항변은 소멸하지만 물적 항변은 남는다":"기한후배서·지시금지 어음은 선의취득 불가이며, 선의취득이 되더라도 소멸하는 것은 인적 항변뿐입니다.","직무집행정지·직무대행자 선임 가처분은 당사자의 신청으로만 하되 급박하면 본안 전에도 할 수 있다":"직무집행정지·직무대행자 가처분은 당사자 신청으로 하며, 급박하면 본안 소 제기 전에도 가능합니다.","질취는 발행주식총수의 20분의 1을 넘지 못한다":"자기주식 질취는 발행주식총수의 20분의 1을 넘을 수 없습니다.","집행임원은 이사가 이사회 소집 청구에 응하지 않으면 법원 허가를 받아 소집하지만 감사는 허가 없이 소집한다":"집행임원이 이사회 소집을 청구해도 이사가 응하지 않으면 법원 허가가 필요하지만 감사는 허가 없이 소집할 수 있습니다.","처분은 정관에 정함이 없으면 이사회가 정하고 이사회 결의로 자기주식을 소각하면 자본금 감소 절차가 필요 없다":"자기주식 처분은 이사회가 정하고, 이사회 결의로 소각하면 자본금 감소 절차가 필요 없습니다.","청구권은 계약이 종료한 날부터 6월이 지나면 소멸한다":"보상청구권은 계약 종료일로부터 6월이 지나면 사라지는 단기 권리입니다.","청산사무가 끝나면 청산인은 지체 없이 결산보고서를 작성해 주주총회 승인을 받고, 승인이 있으면 부정행위가 아닌 한 청산인의 책임을 해제한 것으로 본다":"청산사무가 끝나면 결산보고서를 총회에서 승인받고, 승인이 있으면 부정행위가 아닌 한 청산인의 책임이 해제된 것으로 봅니다.","청산인은 임무가 끝나면 계산서를 작성해 각 사원의 승인을 받는다":"청산인은 임무를 마치면 계산서를 만들어 사원들의 승인을 받아야 합니다.","청산인은 취임 후 지체 없이 재산목록과 대차대조표를 작성해 주주총회 승인을 받고, 정기총회에 대차대조표와 사무보고서를 제출해 승인을 구한다 → 취임일부터 2월 내에 2월 이상의 신고기간을 정해 채권신고를 2회 이상 공고로 최고 → 알고 있는 채권자는 신고하지 않아도 청산에서 제외하지 못한다 → 청산에서 제외된 채권자는 분배되지 않은 잔여재산에 대해서만 변제를 청구할 수 있다":"청산인은 재산목록·대차대조표를 승인받고 채권신고를 공고로 최고하며, 알고 있는 채권자는 제외할 수 없고 제외되면 잔여재산에서만 변제받습니다.","청약과 함께 받은 견품은 청약을 거절해도 청약자의 비용으로 보관한다":"청약자가 보낸 견품은 거절해도 청약자 부담으로 맡아 두어야 합니다.","총사원 과반수로 청산인을 선임하고(없으면 업무집행사원), 사원 1인이나 해산명령·판결로 해산하면 법원이 청산인을 선임한다":"합명회사는 총사원 과반수로 청산인을 정하고, 사원 1인이나 해산명령·판결로 해산하면 법원이 청산인을 선임합니다.","총사원의 동의로 주식회사로만 조직변경할 수 있다":"유한책임회사는 총사원 동의가 있으면 주식회사로만 조직변경할 수 있습니다.","총사원 일치(정관으로 총사원 반수 이상·의결권 4분의 3 이상 가능)와 법원 인가가 필요하고, 발행 주식의 발행가액 총액은 현존 순재산액을 넘지 못한다":"유한회사를 주식회사로 바꾸려면 총사원 일치와 법원 인가가 필요하고 발행 주식의 발행가액 총액은 현존 순재산액을 넘지 못합니다.","총주주의 동의가 있거나 상대방이 그 회사 발행주식총수의 100분의 90 이상을 가지고 있음 → 주주총회 승인을 이사회 승인으로 갈음한다(제374조의3) → 이 경우 계약서 작성일부터 2주 이내에 공고나 통지를 하되 총주주 동의가 있으면 생략한다":"간이 양도는 총주주 동의나 100분의 90 이상 보유 때 이사회 승인으로 대체하며, 공고·통지는 2주 이내이고 총주주 동의 시 생략합니다.","총회는 정관에 달리 정한 바가 없으면 본점소재지나 인접한 곳에 소집한다(제364조)":"총회는 정관에 달리 정함이 없으면 본점 소재지나 인접한 곳에서 소집합니다.","총회 소집은 상법에 다른 규정이 없으면 이사회가 정한다":"총회 소집은 다른 규정이 없을 때 이사회가 결정한다는 것이 원칙입니다.","총회에서 연기나 속행을 결의하면 다시 소집절차를 밟지 않는다":"연기나 속행을 총회에서 결의했다면 소집절차를 다시 밟을 필요가 없습니다.","총회일 10일 전에 서면 또는 각 주주 동의를 받은 전자문서로 통지할 수 있다":"자본금 10억원 미만 회사는 총회 10일 전에 서면이나 동의를 받은 전자문서로 통지할 수 있습니다.","총회일 2주 전에 각 주주에게 서면으로 통지하거나 각 주주의 동의를 받아 전자문서로 통지하며 통지서에는 회의의 목적사항을 적는다":"총회 2주 전에 각 주주에게 서면이나 동의를 받은 전자문서로 통지하고 통지서에 회의 목적사항을 적어야 합니다.","총회일 3일 전에 서면·전자문서로 그 뜻과 이유를 통지하고, 주식의 신탁을 인수하는 등 타인을 위하여 주식을 가진 경우가 아니면 회사가 거부할 수 있다":"의결권 불통일행사는 총회 3일 전에 서면·전자문서로 이유를 통지해야 하며, 타인을 위해 주식을 가진 경우가 아니면 회사가 거부할 수 있습니다.","최후 등기 후 5년이 지난 회사 → 법원행정처장의 관보 공고일부터 2월 내에 영업을 폐지하지 않았다는 신고를 하지 않으면 신고기간 만료 때 해산한 것으로 본다 → 그 후 3년 내에는 특별결의로 계속할 수 있다 → 계속하지 않으면 3년이 지난 때 청산이 종결된 것으로 본다":"5년간 등기가 없는 휴면회사는 공고 후 2월 내 신고하지 않으면 해산으로 보고, 3년 안에 계속 결의가 없으면 청산이 끝난 것으로 봅니다.","출자 1좌의 금액은 100원 이상으로 균일하게 하고 최저자본금과 사원 수 제한은 없다":"출자 1좌 금액은 100원 이상으로 같게 정하며 최저자본금도 사원 수 제한도 없습니다.","취득자의 성명·주소를 주주명부에 적지 않으면 회사에 대항하지 못하고 회사가 양수 사실을 알아도 같다":"양수인의 성명·주소를 주주명부에 적지 않으면 회사가 양수 사실을 알아도 회사에 대항하지 못합니다.","취임 후 3년 내 최종 결산기에 관한 정기총회 종결 때까지":"감사의 임기는 취임 후 3년 내 마지막 결산기의 정기총회가 끝날 때까지입니다.","타인과 영업의 손익 전부를 같이 하는 계약":"타인과 영업의 손익을 전부 같이 하는 계약도 특별결의 대상입니다.","타인이 그 어음으로 제3자에게서 금융을 얻게 할 목적으로 수수하는 어음이다":"융통어음은 타인이 제3자에게서 금융을 얻게 할 목적으로 주고받는 어음입니다.","타인이 등기한 상호는 같은 특별시·광역시·시·군에서 동종영업의 상호로 등기하지 못한다":"같은 시·군 등 지역에서 동종영업이라면 타인이 이미 등기한 상호는 다시 등기할 수 없습니다.","통지가 주주명부상 주소에 계속 3년간 도달하지 않으면 그 주주에게 통지하지 않을 수 있다":"주소로 보낸 통지가 계속 3년 동안 도달하지 않으면 그 주주에게는 더 통지하지 않아도 됩니다.","통지는 어음 반환으로도 할 수 있고 통지하지 않아도 상환청구권을 잃지 않으며 과실로 생긴 손해를 어음금액 한도에서 배상한다":"통지는 어음 반환으로도 가능하고, 통지 안 해도 청구권은 남지만 과실로 생긴 손해는 어음금액 한도에서 배상합니다.","통지하지 않지만 주식매수청구권이 인정되는 안건이 있으면 통지한다":"의결권 없는 주주에게는 통지하지 않지만 주식매수청구권이 인정되는 안건이 있으면 통지해야 합니다.","특별결의는 출석 의결권의 3분의 2 이상과 발행주식총수의 3분의 1 이상":"특별결의의 정족수는 출석 의결권 3분의 2와 발행주식총수 3분의 1입니다.","특별이익과 설립비용·보수액은 공증인의 조사·보고로, 현물출자와 재산인수는 공인된 감정인의 감정으로 검사인 조사를 갈음하고 결과는 법원에 보고한다(제299조의2)":"검사인 조사를 갈음해 특별이익·설립비용은 공증인이, 현물출자·재산인수는 감정인이 조사·감정하고 법원에 보고합니다.","특별이해관계로 의결권을 행사하지 못한 주주는 결의가 현저히 부당하고 행사했으면 저지할 수 있었을 때 결의일부터 2월 내에 제기하며 이 소에는 재량기각이 없다":"특별이해관계로 의결권을 못 한 주주는 결의가 현저히 부당하면 결의일부터 2월 안에 소를 내며 이 소에는 재량기각이 없습니다.","특별이해관계인의 주식과 감사 선임 때 3%를 넘는 부분은 출석 의결권 수에 넣지 않는다":"특별이해관계인 주식과 감사 선임 때 3% 초과분은 출석 의결권 수에서 제외합니다.","판결은 소급효가 없어 확정 전의 법률관계에 영향을 주지 않는다":"합병무효 판결은 소급하지 않아 확정 전 법률관계에는 영향이 없습니다.","판결이 확정되면 본점 소재지에서 등기한다":"감자무효 판결이 나면 본점에서 그 사실을 등기합니다.","판결이 확정되면 신주는 장래에 대하여 효력을 잃으며 회사는 납입금을 반환한다":"무효판결이 확정되면 신주는 장래를 향해 효력을 잃고 회사는 납입금을 돌려줍니다.","판례상 악의는 항변사유를 아는 것으로 부족하고 자기가 취득하면 항변이 절단되어 채무자가 손해를 입는다는 사정까지 알아야 한다":"악의가 있다고 하려면 항변사유를 안 것만으로는 모자라고 채무자가 해를 입는다는 것까지 알아야 합니다.","폐쇄기간은 3월을 넘지 못하고 기준일은 권리행사일 전 3월 내의 날로 정하며 2주간 전에 공고하되 정관에 정했으면 공고가 필요 없다":"명부 폐쇄기간은 3월 이내이고 기준일은 권리행사일 전 3월 이내이며, 정관에 정했다면 따로 공고하지 않아도 됩니다.","피담보채권과 목적물 사이의 견련성은 필요 없다":"상사유치권은 민사유치권과 달리 피담보채권과 목적물 사이의 견련성이 필요 없습니다.","피배서인은 어음상 모든 권리를 행사하지만 대리를 위한 배서만 할 수 있고 어음채무자는 배서인에게 대항할 수 있는 항변으로만 소지인에게 대항한다":"추심위임배서의 피배서인은 어음상 모든 권리를 행사하나 대리를 위해서만 배서할 수 있고 채무자는 배서인에 대한 항변으로만 대항합니다.","피위조자는 소지인의 선의·악의와 관계없이 위조의 항변으로 책임을 면하고 판례상 피위조자가 위조를 주장하면 소지인이 기명날인의 진정을 증명해야 한다":"위조된 어음은 선의·악의와 상관없이 위조의 항변으로 책임을 피하며, 이를 주장하면 소지인이 진정함을 증명해야 합니다.","한도를 넘은 배당에 대하여 회사채권자는 배당한 이익을 회사에 반환하라고 청구할 수 있다":"위법배당이 있으면 회사채권자가 그 배당액을 회사에 돌려놓으라고 청구할 수 있습니다.","합명→합자는 총사원의 동의, 유한책임사원이 모두 퇴사한 합자회사의 합명회사 변경은 무한책임사원 전원의 동의":"합명에서 합자로의 변경은 총사원 동의, 유한책임사원이 모두 퇴사한 합자의 합명 변경은 무한책임사원 전원 동의가 필요합니다.","합명·합자·유한책임·주식·유한회사의 5종이다(상호회사는 아니다)":"회사의 종류는 합명·합자·유한책임·주식·유한회사의 5종이며 상호회사는 포함되지 않습니다.","합명회사는 사원, 유한책임회사는 사원과 업무집행자, 유한회사는 사원·이사·감사가 제기한다":"설립무효의 소의 제소권자는 회사 종류별로 다르며 합명회사는 사원, 유한회사는 사원·이사·감사입니다.","합명회사는 정관이나 총사원의 동의로 재산처분방법을 정해 임의청산할 수 있고, 이때 해산사유가 있은 날부터 2주간 내에 재산목록과 대차대조표를 작성한다":"합명회사는 정관이나 총사원 동의로 재산처분방법을 정해 임의청산하고 해산사유일부터 2주 안에 재산목록 등을 작성합니다.","합병계약서는 주주총회 특별결의로 승인하고, 계약서에 정관변경을 적어 승인하면 따로 정관변경 결의가 필요 없다 → 합병대가는 전부를 금전이나 그 밖의 재산으로 줄 수 있고, 존속회사는 대가로 줄 모회사 주식을 취득할 수 있다(삼각합병) → 결의일부터 2주 내에 1월 이상의 기간을 정해 채권자 이의를 공고·최고 → 합병 등기는 본점 소재지에서 2주 내에 한다":"합병은 특별결의로 승인하고 대가를 금전으로도 줄 수 있으며(삼각합병), 채권자 이의 공고·최고와 등기를 정해진 기간 안에 합니다.","합병·영업 전부 양수, 권리 실행, 단주 처리, 주식매수청구권 행사의 경우에는 배당가능이익과 관계없이 취득할 수 있다":"합병, 영업 전부 양수, 권리 실행, 단주 처리, 매수청구권 행사 때는 이익이 없어도 자기주식을 취득할 수 있습니다.","합병으로 소멸하는 회사의 법정준비금은 존속·신설회사가 승계할 수 있다":"소멸회사의 법정준비금은 합병 후 존속·신설회사가 이어받을 수 있습니다.","합병 후 회사가 주식회사인 주식회사·유한회사 합병은 법원 인가를 받아야 효력이 있다":"합병 후 존속회사가 주식회사인 경우 주식회사·유한회사 합병은 법원 인가가 있어야 합병 효력이 생깁니다.","해산판결 청구이고, 주주제안과 집중투표만 의결권 없는 주식을 뺀 발행주식총수가 기준이다":"가장 높은 비율 요건은 해산판결 청구이고, 주주제안과 집중투표만 의결권 없는 주식을 뺀 총수를 기준으로 합니다.","해산하면 파산의 경우 외에는 이사가 지체 없이 주주에게 통지한다":"해산하면 파산의 경우를 빼고 이사가 지체 없이 주주에게 해산 사실을 통지합니다.","해산하면 합병·분할·파산의 경우 외에는 이사가 청산인이 되고 정관이나 총회로 다른 사람을 정할 수 있으며, 청산인 임기에는 제한이 없다":"청산인은 이사가 맡는 것이 원칙이고 정관·총회로 달리 정할 수 있으며 청산인에게 임기 제한은 없습니다.","해산한 회사도 청산의 목적 범위 안에서는 존속한다":"해산한 회사라도 청산 목적 범위에서는 계속 존재합니다.","현물출자·재산인수 총액이 자본금의 5분의 1과 5천만원을 넘지 않는 등의 경우에는 검사인 조사가 필요 없다":"현물출자·재산인수 총액이 자본금의 5분의 1과 5천만원을 넘지 않으면 검사인 조사를 생략할 수 있습니다.","현저히 불공정한 합병비율도 무효 원인이 될 수 있다":"불공정한 합병비율도 합병무효의 원인이 될 수 있습니다.","화폐·유가증권 등 고가물은 송하인이 종류와 가액을 명시한 경우에만 운송인이 책임진다":"송하인이 종류와 가액을 알리지 않으면 화폐·유가증권 같은 고가물은 운송인이 책임지지 않습니다.","확정일출급 등은 지급할 날 또는 그 이후 2거래일 내에 지급제시하고(제38조)":"확정일출급 어음은 지급할 날 또는 그 뒤 2거래일 안에 지급제시해야 합니다.","확정일출급 등의 지급거절증서는 지급할 날 이후 2거래일 내에 작성시킨다":"확정일출급 어음 등의 거절증서는 지급할 날 이후 2거래일 안에 만들어야 합니다.","환수한 날이나 제소된 날부터 6개월":"배서인의 다른 배서인·발행인에 대한 청구권은 환수한 날이나 제소된 날부터 6개월 시효입니다.","환어음 발행인은 인수와 지급을 담보하고 인수무담보 문구는 유효하지만 지급무담보 문구는 적지 않은 것으로 본다":"환어음 발행인은 인수와 지급을 책임지며 인수무담보 약정만 허용되고 지급무담보 약정은 무효입니다.","환어음에는 환어음 문자, 조건 없는 지급위탁, 지급인, 만기, 지급지, 수취인, 발행일과 발행지, 발행인의 기명날인 또는 서명을 적고(제1조) 약속어음에는 지급인이 없다":"환어음에는 문자, 조건 없는 지급위탁, 지급인, 만기, 지급지, 수취인, 발행일·지, 서명이 들어가며 약속어음에는 지급인이 없습니다.","회사가 상환하려면 취득일 2주 전에 통지하되 공고로 갈음할 수 있고 상환해도 자본금은 줄지 않는다":"상환을 하려는 회사는 취득일 2주 전에 통지하거나 공고하며, 상환해도 자본금은 그대로입니다.","회사가 성립하지 못하면 설립비용은 발기인이 부담한다":"회사가 설립되지 않으면 설립에 든 비용은 발기인이 떠안습니다.","회사가 성립 후 2년 내에 성립 전부터 있던 영업용 재산을 자본금의 100분의 5 이상의 대가로 취득하는 계약을 하면 제374조를 준용하여 특별결의를 거친다(제375조)":"사후설립은 성립 후 2년 안에 성립 전부터 있던 영업용 재산을 자본금의 100분의 5 이상 대가로 취득하는 계약으로 특별결의가 필요합니다.","회사는 자본금의 2분의 1이 될 때까지 매 결산기 이익배당액의 10분의 1 이상을 이익준비금으로 적립하고, 주식배당은 적립 대상에서 제외된다":"이익준비금은 자본금의 2분의 1이 될 때까지 매 결산기 이익배당액의 10분의 1 이상 적립하며 주식배당은 제외합니다.","회사는 종류가 달라도 합병할 수 있으나 한쪽이 주식회사·유한회사·유한책임회사이면 존속·신설회사도 그중 하나여야 하고, 해산 후의 회사는 존립 중의 회사를 존속회사로 하는 경우에만 합병한다":"합병은 회사 종류가 달라도 가능하지만 주식·유한·유한책임회사가 끼면 존속·신설회사도 그중 하나여야 합니다.","회사는 직전 결산기 배당가능이익 한도에서 자기 명의와 계산으로 거래소 매수나 균등 조건으로 취득하고, 취득가액 한도 등은 주주총회 결의로 정하되 이사회 결의로 이익배당을 할 수 있는 회사는 이사회 결의로 정한다":"자기주식은 직전 결산기 배당가능이익 한도에서 자기 명의·계산으로 거래소 매수나 균등 조건으로 취득하고 총회 또는 이사회 결의로 정합니다.","회사 상호에는 종류에 따른 문자를 쓰고 회사가 아니면 회사임을 표시하는 문자를 쓰지 못한다":"회사 상호에는 회사 종류를 나타내는 문자를 써야 하고, 회사가 아닌 자는 회사임을 표시하는 문자를 쓰지 못합니다.","회사 성립 후 2년이 지난 뒤 주주총회 특별결의(최저발행가액 결정)와 법원 인가를 얻어 한다":"액면미달 발행은 설립 후 2년이 지난 뒤 특별결의와 법원 인가를 받아야 가능합니다.","회사에 대한 손해배상책임은 총주주의 동의로 면제할 수 있고, 제3자에 대한 책임은 악의 또는 중대한 과실이 있을 때만 진다":"발기인의 회사에 대한 책임은 총주주 동의로 면제 가능하고, 제3자에 대해서는 악의·중과실이 있을 때만 책임이 있습니다.","회사에 대한 책임은 총주주의 동의로 면제하고, 정관으로 최근 1년 보수의 6배(사외이사·독립이사 3배)를 넘는 금액을 면제할 수 있다":"책임 면제는 총주주 동의로 하거나, 정관으로 최근 1년 보수의 6배(사외이사 3배) 초과분에 한해 할 수 있습니다.","회사 영업에 중대한 영향을 미치는 다른 회사의 영업 전부 또는 일부의 양수는 제434조의 특별결의를 거친다":"회사 영업에 중대한 영향을 주는 다른 회사 영업의 전부 또는 일부를 양수할 때에도 특별결의가 필요합니다.","회사와 이사 사이의 소송은 감사가 회사를 대표한다":"이사를 상대로 한 회사의 소송에서는 감사가 회사를 대표합니다.","회사와 이사 사이의 소에서는 사원총회가 회사를 대표할 자를 정한다":"이사를 상대하는 소송에서는 사원총회가 회사를 대표할 사람을 선정합니다.","회사 장부와 영업·청산에 관한 중요서류는 청산종결 등기 후 10년(전표류 5년) 보존한다":"회사 장부와 중요서류는 청산종결 등기 후 10년, 전표류는 5년 보존합니다.","회사 재산으로 채무를 완제할 수 없으면 각 사원이 연대하여 변제하고, 사원은 회사가 가진 항변으로 채권자에게 대항할 수 있다":"회사 재산으로 채무를 다 못 갚으면 사원이 연대해 갚고, 사원은 회사가 가진 항변을 채권자에게 주장할 수 있습니다.","회일 1주간 전에 각 이사와 감사에게 통지하되 정관으로 단축할 수 있고 이사·감사 전원이 동의하면 절차 없이 열 수 있다":"이사회는 회일 1주간 전에 이사와 감사에게 통지하며 정관으로 단축할 수 있고 전원 동의가 있으면 절차 없이 열 수 있습니다."}});if(window.DIAGRAM&&DIAGRAM.tnFlush)DIAGRAM.tnFlush();
/*tnote-data-end*/
